package com.slayerprepassistant.gear;

import static org.junit.Assert.assertEquals;

import com.slayerprepassistant.bank.BankSnapshot;
import com.slayerprepassistant.bank.OwnershipState;
import com.slayerprepassistant.bank.PlayerInventoryState;
import java.time.Instant;
import java.util.Collections;
import java.util.HashSet;
import org.junit.Test;

public class GearMatcherTest
{
	@Test
	public void matchesEquippedVariantByName()
	{
		PlayerInventoryState state = new PlayerInventoryState(
			Collections.emptyMap(),
			Collections.emptyMap(),
			new HashSet<>(Collections.singletonList("Slayer helmet (i)")),
			Collections.emptySet(),
			BankSnapshot.emptyUnknown());

		OwnershipState ownership = new GearMatcher().ownershipFor(new RecommendedItem("Slayer helmet"), state);

		assertEquals(OwnershipState.EQUIPPED, ownership);
	}

	@Test
	public void matchesKnownBankVariantByName()
	{
		BankSnapshot bank = new BankSnapshot(Collections.emptyMap(), new HashSet<>(Collections.singletonList("Black mask (10)")), Instant.now());
		PlayerInventoryState state = new PlayerInventoryState(Collections.emptyMap(), Collections.emptyMap(), Collections.emptySet(), Collections.emptySet(), bank);

		OwnershipState ownership = new GearMatcher().ownershipFor(new RecommendedItem("Black mask"), state);

		assertEquals(OwnershipState.OWNED_IN_BANK, ownership);
	}

	@Test
	public void doesNotMatchDifferentNumberedUpgradeTiers()
	{
		BankSnapshot bank = new BankSnapshot(Collections.emptyMap(), new HashSet<>(Collections.singletonList("Rada's blessing 3")), Instant.now());
		PlayerInventoryState state = new PlayerInventoryState(Collections.emptyMap(), Collections.emptyMap(), Collections.emptySet(), Collections.emptySet(), bank);

		OwnershipState ownership = new GearMatcher().ownershipFor(new RecommendedItem("Rada's blessing 4"), state);

		assertEquals(OwnershipState.UNKNOWN, ownership);
	}

	@Test
	public void inventoryOwnershipIgnoresEquippedItems()
	{
		PlayerInventoryState state = new PlayerInventoryState(
			Collections.emptyMap(),
			Collections.emptyMap(),
			new HashSet<>(Collections.singletonList("Prayer potion")),
			Collections.emptySet(),
			new BankSnapshot(Collections.emptyMap(), Collections.emptySet(), Instant.now()));

		OwnershipState ownership = new GearMatcher().ownershipForInventoryItem(new RecommendedItem("Prayer potion"), state);

		assertEquals(OwnershipState.MISSING, ownership);
	}
}

package com.slayerprepassistant.gear;

import static org.junit.Assert.assertEquals;

import com.slayerprepassistant.bank.BankSnapshot;
import com.slayerprepassistant.bank.OwnershipState;
import com.slayerprepassistant.bank.PlayerInventoryState;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.OptionalInt;
import org.junit.Test;

public class LoadoutBuilderTest
{
	private final LoadoutBuilder builder = new LoadoutBuilder(new GearMatcher());

	@Test
	public void bestIOwnChoosesHighestRankedOwnedAlternative()
	{
		RecommendedItem best = new RecommendedItem("Best sword", new HashSet<>(Collections.singletonList(1)));
		RecommendedItem owned = new RecommendedItem("Owned sword", new HashSet<>(Collections.singletonList(2)));
		GearRecommendation recommendation = new GearRecommendation(GearSlot.WEAPON, Arrays.asList(
			new GearTier(1, Collections.singletonList(best)),
			new GearTier(2, Collections.singletonList(owned))));
		HashMap<Integer, Integer> bank = new HashMap<>();
		bank.put(2, 1);

		LoadoutResult result = builder.build(Collections.singletonList(recommendation),
			new PlayerInventoryState(Collections.emptyMap(), Collections.emptyMap(), new BankSnapshot(bank, Instant.now())),
			LoadoutMode.BEST_I_OWN);

		assertEquals("Owned sword", result.getGearMatches().get(0).getItem().getName());
		assertEquals(OwnershipState.OWNED_IN_BANK, result.getGearMatches().get(0).getOwnershipState());
	}

	@Test
	public void unknownBankDoesNotMarkRecommendedItemMissing()
	{
		RecommendedItem item = new RecommendedItem("Known id", new HashSet<>(Collections.singletonList(99)));
		GearRecommendation recommendation = new GearRecommendation(GearSlot.HEAD, Collections.singletonList(new GearTier(1, Collections.singletonList(item))));

		LoadoutResult result = builder.build(Collections.singletonList(recommendation), PlayerInventoryState.unknownBank(), LoadoutMode.BEST_I_OWN);

		assertEquals(OwnershipState.UNKNOWN, result.getGearMatches().get(0).getOwnershipState());
	}

	@Test
	public void maxChoosesHighestRankedWikiRecommendationEvenWhenMissing()
	{
		RecommendedItem best = new RecommendedItem("Best sword", new HashSet<>(Collections.singletonList(1)));
		RecommendedItem owned = new RecommendedItem("Owned sword", new HashSet<>(Collections.singletonList(2)));
		GearRecommendation recommendation = new GearRecommendation(GearSlot.WEAPON, Arrays.asList(
			new GearTier(1, Collections.singletonList(best)),
			new GearTier(2, Collections.singletonList(owned))));
		HashMap<Integer, Integer> bank = new HashMap<>();
		bank.put(2, 1);

		LoadoutResult result = builder.build(Collections.singletonList(recommendation),
			new PlayerInventoryState(Collections.emptyMap(), Collections.emptyMap(), new BankSnapshot(bank, Instant.now())),
			LoadoutMode.MAX);

		assertEquals("Best sword", result.getGearMatches().get(0).getItem().getName());
		assertEquals(OwnershipState.MISSING, result.getGearMatches().get(0).getOwnershipState());
	}
}

package com.slayerprepassistant;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class PluginUrlsTest
{
	@Test
	public void wikiApiUrlUsesDeclaredEndpoint()
	{
		assertEquals(
			"https://oldschool.runescape.wiki/api.php",
			PluginUrls.osrsWikiApiEndpointBuilder().build().toString());
	}

	@Test
	public void wikiPageUrlUsesDeclaredWikiHost()
	{
		assertEquals(
			"https://oldschool.runescape.wiki/w/Bank_filler",
			PluginUrls.osrsWikiPageUrl("Bank filler"));
	}

	@Test
	public void wikiImageUrlRebuildsWikiImagePathAgainstDeclaredHost()
	{
		assertEquals(
			"https://oldschool.runescape.wiki/images/Item.png?abc=123",
			PluginUrls.osrsWikiImageUrlFromMediaWikiSource("https://oldschool.runescape.wiki/images/Item.png?abc=123").toString());
	}

	@Test
	public void wikiImageUrlAcceptsRelativeWikiImagePath()
	{
		assertEquals(
			"https://oldschool.runescape.wiki/images/Item.png?abc=123",
			PluginUrls.osrsWikiImageUrlFromMediaWikiSource("/images/Item.png?abc=123").toString());
	}

	@Test
	public void wikiImageUrlRejectsForeignHost()
	{
		assertNull(PluginUrls.osrsWikiImageUrlFromMediaWikiSource("https://example.com/images/Item.png"));
	}

	@Test
	public void wikiImageUrlRejectsNonImageWikiPath()
	{
		assertNull(PluginUrls.osrsWikiImageUrlFromMediaWikiSource("https://oldschool.runescape.wiki/w/Bank_filler"));
	}
}

package com.slayerprepassistant.readiness;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import com.slayerprepassistant.bank.OwnershipState;
import com.slayerprepassistant.gear.GearMatch;
import com.slayerprepassistant.gear.GearSlot;
import com.slayerprepassistant.gear.LoadoutMode;
import com.slayerprepassistant.gear.LoadoutResult;
import com.slayerprepassistant.gear.RecommendedItem;
import java.util.Collections;
import org.junit.Test;

public class ReadinessServiceTest
{
	@Test
	public void unknownGearReducesReadinessWithoutMarkingMissing()
	{
		ReadinessResult result = new ReadinessService().evaluate(
			Collections.emptyList(),
			new LoadoutResult(LoadoutMode.BEST_I_OWN, Collections.singletonList(new GearMatch(GearSlot.WEAPON, new RecommendedItem("Leaf-bladed sword"), OwnershipState.UNKNOWN, 1))));

		assertEquals(97, result.getPercentage());
		assertFalse(result.getUnknownItems().isEmpty());
	}
}

package com.slayerprepassistant.wiki;

import static org.junit.Assert.assertEquals;

import com.slayerprepassistant.task.TargetOption;
import java.util.Arrays;
import org.junit.Test;

public class WikiPageCandidatesTest
{
	@Test
	public void strategyPagesKeepPreferredFirstAndRemoveDuplicates()
	{
		TargetOption target = new TargetOption("Bank fillers", "Bank fillers", "Strategies/Bank fillers");

		assertEquals(
			Arrays.asList("Bank fillers/Strategies", "Strategies/Bank fillers", "Strategies/Bank filler", "Bank filler/Strategies", "Slayer_task/Bank fillers", "Slayer_task/Bank filler"),
			WikiPageCandidates.strategyPages(target, "Bank fillers/Strategies"));
	}

	@Test
	public void variantPagesTryTaskPageAliases()
	{
		TargetOption target = new TargetOption("Dust devils", "Dust devils", "Strategies/Dust devils");

		assertEquals(
			Arrays.asList("Dust devils", "Slayer_task/Dust devils", "Dust devil", "Slayer_task/Dust devil"),
			WikiPageCandidates.variantPages(target));
	}
}

