		JPanel meta = new JPanel(new BorderLayout(5, 0));
		meta.setBackground(rowBackground);
		meta.add(label("x " + Math.max(1, recommendation.getMinimumQuantity()), MUTED, false, FONT_XS), BorderLayout.WEST);
