	private String wrapHtml(String text, int width, boolean centered)
	{
		String align = centered ? "; text-align:center" : "";
		return "<html><body style='width:" + Math.max(1, width) + "px" + align + "'>" + escape(text) + "</body></html>";
	}

	private String escape(String text)
	{
		return (text == null ? "" : text)
				.replace("&", "&amp;")
				.replace("<", "&lt;")
				.replace(">", "&gt;");
	}

	private JButton styledButton(String text)
	{
		return styledButton(new JButton(text));
	}

	private JButton styledButton(JButton button)
	{
		button.setForeground(TEXT);
		button.setBackground(CONTROL_BASE);
		button.setFont(button.getFont().deriveFont(Font.PLAIN, FONT_SM));
		button.setFocusPainted(false);
		button.setOpaque(true);
		button.setContentAreaFilled(true);
		button.setBorder(controlBorder());
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return button;
	}

	private void applyButtonHover(JButton button, BooleanSupplier selectedSupplier)
	{
		if (button == null)
		{
			return;
		}
		applyButtonState(button, selectedSupplier, false, false);
		button.addMouseListener(new MouseAdapter()
		{
			private boolean hovering;
			private boolean pressing;

			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovering = true;
				applyButtonState(button, selectedSupplier, true, pressing);
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovering = false;
				pressing = false;
				applyButtonState(button, selectedSupplier, false, false);
			}

			@Override
			public void mousePressed(MouseEvent event)
			{
				pressing = true;
				applyButtonState(button, selectedSupplier, hovering, true);
			}

			@Override
			public void mouseReleased(MouseEvent event)
			{
				pressing = false;
				applyButtonState(button, selectedSupplier, hovering, false);
			}
		});
	}

	private void applyButtonState(JButton button, BooleanSupplier selectedSupplier, boolean hover, boolean pressed)
	{
		boolean selected = selectedSupplier != null && selectedSupplier.getAsBoolean();
		button.setBackground(pressed ? CONTROL_PRESSED : selected ? CONTROL_SELECTED : hover ? CONTROL_HOVER : CONTROL_BASE);
		button.setForeground(selected ? GOLD : hover ? Color.WHITE : TEXT);
		button.setBorder(controlBorder(selected, hover || pressed));
		button.repaint();
	}

	private void styleCombo(JComboBox<?> comboBox)
	{
		comboBox.setForeground(TEXT);
		comboBox.setBackground(new Color(20, 20, 20));
		comboBox.setFont(comboBox.getFont().deriveFont(Font.PLAIN, FONT_SM));
		comboBox.setBorder(controlBorder());
		comboBox.setFocusable(false);
		comboBox.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		comboBox.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				comboBox.setBorder(controlBorder(false, true));
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				comboBox.setBorder(controlBorder(false, false));
			}
		});
	}

	private Border controlBorder()
	{
		return controlBorder(false, false);
	}

	private Border controlBorder(boolean selected, boolean hover)
	{
		Color borderColor = selected ? GOLD : hover ? BORDER_HOVER : BORDER;
		return BorderFactory.createCompoundBorder(
				roundedBorder(borderColor, CONTROL_RADIUS),
				BorderFactory.createEmptyBorder(4, 4, 4, 4));
	}

	private void setBackgroundRecursive(Component component, Color background)
	{
		if (component == null || background == null)
		{
			return;
		}
		component.setBackground(background);
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				setBackgroundRecursive(child, background);
			}
		}
	}

	private String methodLabel(CombatMethod method)
	{
		switch (method)
		{
			case MELEE:
				return "Melee";
			case RANGED:
				return "Ranged";
			case MAGIC:
				return "Magic";
			default:
				return method.toString();
		}
	}

	private ImageIcon methodIcon(CombatMethod method)
	{
		Skill skill;
		switch (method)
		{
			case MELEE:
				skill = Skill.ATTACK;
				break;
			case RANGED:
				skill = Skill.RANGED;
				break;
			case MAGIC:
				skill = Skill.MAGIC;
				break;
			default:
				skill = Skill.ATTACK;
		}
		BufferedImage image = skillIconManager.getSkillImage(skill);
		return image == null ? null : new ImageIcon(fitImage(image, 22, 22));
	}

	private static BufferedImage fitImage(Image image, int maxWidth, int maxHeight)
	{
		if (image == null || maxWidth <= 0 || maxHeight <= 0)
		{
			return new BufferedImage(Math.max(1, maxWidth), Math.max(1, maxHeight), BufferedImage.TYPE_INT_ARGB);
		}
		int sourceWidth = image.getWidth(null);
		int sourceHeight = image.getHeight(null);
		if (sourceWidth <= 0 || sourceHeight <= 0)
		{
			return new BufferedImage(maxWidth, maxHeight, BufferedImage.TYPE_INT_ARGB);
		}

		double scale = Math.min(1.0, Math.min(maxWidth / (double) sourceWidth, maxHeight / (double) sourceHeight));
		int width = Math.max(1, (int) Math.round(sourceWidth * scale));
		int height = Math.max(1, (int) Math.round(sourceHeight * scale));
		BufferedImage fitted = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = fitted.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return fitted;
	}

	private static ImageIcon resourceIcon(String path, int size)
	{
		if (path == null || path.trim().isEmpty() || size <= 0)
		{
			return null;
		}
		try (InputStream stream = SlayerPrepAssistantPanel.class.getResourceAsStream(path))
		{
			if (stream == null)
			{
				return null;
			}
			BufferedImage image = javax.imageio.ImageIO.read(stream);
			if (image == null)
			{
				return null;
			}
			return new ImageIcon(ImageUtil.resizeImage(image, size, size));
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	private Border roundedBorder(Color color, int radius)
	{
		return new RoundedBorder(color, radius);
	}

	private Border compoundBorder()
	{
		return BorderFactory.createCompoundBorder(roundedBorder(BORDER, CARD_RADIUS), BorderFactory.createEmptyBorder(7, 6, 7, 6));
	}

	private Color statusColor(OwnershipState state)
	{
		if (state == null)
		{
			return MUTED;
		}
		switch (state)
		{
			case EQUIPPED:
				return GREEN;
			case OWNED_IN_INVENTORY:
				return BLUE;
			case OWNED_IN_BANK:
				return YELLOW;
			case MISSING:
				return RED;
			case UNKNOWN:
			default:
				return MUTED;
		}
	}

	private String statusText(OwnershipState state)
	{
		if (state == null)
		{
			return "Unknown";
		}
		switch (state)
		{
			case EQUIPPED:
				return "Equipped";
			case OWNED_IN_INVENTORY:
				return "Inventory";
			case OWNED_IN_BANK:
				return "Bank";
			case MISSING:
				return "Missing";
			case UNKNOWN:
			default:
				return "Unknown";
		}
	}


	private String itemKey(RecommendedItem item)
	{
		if (item == null)
		{
			return "";
		}

		String name = ItemResolver.canonicalKey(item.getName());
		if (!name.isEmpty())
		{
			return "name:" + name;
		}
		return item.getItemIds().stream()
			.filter(java.util.Objects::nonNull)
			.min(Integer::compareTo)
			.map(itemId -> "id:" + itemId)
			.orElse("");
	}

	private String normalizedKey(String value)
	{
		return safeText(value).trim().toLowerCase(Locale.ROOT);
	}

	private String safeText(String value)
	{
		return value == null ? "" : value;
	}

	private void runOnEdt(Runnable action)
	{
		if (action == null)
		{
			return;
		}

		if (SwingUtilities.isEventDispatchThread())
		{
			action.run();
		}
		else
		{
			SwingUtilities.invokeLater(action);
		}
	}

	private Component spacer(int height)
	{
		return Box.createVerticalStrut(height);
	}

	private void refreshUi()
	{
		if (taskCardPanel != null && taskCardPanel.isVisible())
		{
			fitHeight(taskCardPanel);
		}
		fitHeight(pinnedPanel);
		if (controlsPanel.isVisible())
		{
			fitHeight(controlsPanel);
		}
		updateCollapsibleSectionHeights(body);
		resultPanel.revalidate();
		body.revalidate();
		revalidate();
		repaint();
	}

	private void updateCollapsibleSectionHeights(Component component)
	{
		if (component instanceof CollapsibleSection)
		{
			((CollapsibleSection) component).updateHeight();
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				updateCollapsibleSectionHeights(child);
			}
		}
	}

}

package com.slayerprepassistant.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.function.IntSupplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

class SkeletonSection extends RoundedPanel
{
	private final IntSupplier frameSupplier;

	SkeletonSection(String title, int rows, boolean equipment, IntSupplier frameSupplier)
	{
		super(new BorderLayout(0, 6), SlayerPrepAssistantPanel.PANEL, SlayerPrepAssistantPanel.CARD_RADIUS);
		this.frameSupplier = frameSupplier == null ? () -> 0 : frameSupplier;

		setBorder(BorderFactory.createCompoundBorder(
				new RoundedBorder(SlayerPrepAssistantPanel.BORDER, SlayerPrepAssistantPanel.CARD_RADIUS),
				BorderFactory.createEmptyBorder(7, 6, 7, 6)));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(SlayerPrepAssistantPanel.PANEL);
		header.add(label(title), BorderLayout.WEST);
		add(header, BorderLayout.NORTH);

		int effectiveRows = Math.max(0, rows);
		JPanel body = equipment ? skeletonEquipmentRows(effectiveRows) : skeletonInventoryRows(effectiveRows);
		add(body, BorderLayout.CENTER);
		fitHeight(this);
	}

	private JPanel skeletonEquipmentRows(int rows)
	{
		JPanel panel = verticalPanel(SlayerPrepAssistantPanel.PANEL_LIGHT);
		panel.setBorder(BorderFactory.createLineBorder(new Color(45, 45, 42)));
		for (int i = 0; i < rows; i++)
		{
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setBackground(i % 2 == 0 ? new Color(25, 26, 25) : new Color(21, 22, 22));
			row.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
			row.add(new SkeletonBlock(30, 30, frameSupplier), BorderLayout.WEST);

			JPanel text = verticalPanel(row.getBackground());
			text.add(new SkeletonBlock(56, 8, frameSupplier));
			text.add(Box.createVerticalStrut(4));
			text.add(new SkeletonBlock(i % 3 == 0 ? 96 : 120, 10, frameSupplier));
			row.add(text, BorderLayout.CENTER);
			row.add(new SkeletonBlock(10, 10, frameSupplier), BorderLayout.EAST);
			panel.add(row);
		}
		return panel;
	}

	private JPanel skeletonInventoryRows(int rows)
	{
		JPanel panel = verticalPanel(SlayerPrepAssistantPanel.PANEL_LIGHT);
		panel.setBorder(BorderFactory.createLineBorder(new Color(45, 45, 42)));
		for (int i = 0; i < Math.max(1, rows); i++)
		{
			JPanel row = new JPanel(new BorderLayout(7, 0));
			row.setBackground(i % 2 == 0 ? new Color(25, 26, 25) : new Color(21, 22, 22));
			row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 5));
			row.add(new SkeletonBlock(28, 28, frameSupplier), BorderLayout.WEST);
			row.add(new SkeletonBlock(i % 2 == 0 ? 92 : 110, 10, frameSupplier), BorderLayout.CENTER);
			row.add(new SkeletonBlock(10, 10, frameSupplier), BorderLayout.EAST);
			panel.add(row);
		}
		return panel;
	}

	private JPanel verticalPanel(Color background)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(background == null ? SlayerPrepAssistantPanel.PANEL : background);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private JLabel label(String text)
	{
		JLabel label = new JLabel(text == null ? "" : text);
		label.setForeground(SlayerPrepAssistantPanel.GOLD);
		Font baseFont = label.getFont();
		if (baseFont != null)
		{
			label.setFont(baseFont.deriveFont(Font.BOLD, SlayerPrepAssistantPanel.FONT_XS));
		}
		return label;
	}

	private void fitHeight(Component component)
	{
		if (component == null)
		{
			return;
		}
		Dimension preferred = component.getPreferredSize();
		int prefHeight = preferred != null ? preferred.height : 50;
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, prefHeight));
	}

	private static class SkeletonBlock extends JComponent
	{
		private final IntSupplier frameSupplier;

		SkeletonBlock(int preferredWidth, int preferredHeight, IntSupplier frameSupplier)
		{
			this.frameSupplier = frameSupplier == null ? () -> 0 : frameSupplier;
			Dimension dim = new Dimension(Math.max(1, preferredWidth), Math.max(1, preferredHeight));
			setPreferredSize(dim);
			setMinimumSize(dim);
			setMaximumSize(dim);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			super.paintComponent(graphics);
			if (graphics == null)
			{
				return;
			}
			Graphics2D g = (Graphics2D) graphics.create();
			if (g == null)
			{
				return;
			}
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int width = getWidth();
				int height = getHeight();
				if (width <= 0 || height <= 0)
				{
					return;
				}

				int frame = frameSupplier.getAsInt();
				int pulse = Math.abs(6 - frame);
				int shade = 31 + pulse * 3;
				int radius = SlayerPrepAssistantPanel.CONTROL_RADIUS;
				g.setColor(new Color(shade, shade, Math.max(24, shade - 5)));
				g.fillRoundRect(0, 0, width, height, radius, radius);

				g.setColor(new Color(100, 86, 52, 70));
				int shimmerX = (frame * (width + 16) / 12) - 16;
				g.fillRoundRect(shimmerX, 0, Math.max(8, width / 3), height, radius, radius);
			}
			finally
			{
				g.dispose();
			}
		}
	}
}

package com.slayerprepassistant.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.Border;

class CollapsibleSection extends RoundedPanel
{
	private final String title;
	private final String summary;
	private final Icon icon;
	private final JPanel body;
	private final Runnable refresh;
	private boolean open;

	CollapsibleSection(String title, String summary, Icon icon, boolean defaultOpen, JPanel body, Runnable refresh)
	{
		super(new BorderLayout(0, 5), SlayerPrepAssistantPanel.PANEL, SlayerPrepAssistantPanel.CARD_RADIUS);
		this.title = title == null ? "" : title;
		this.summary = summary == null ? "" : summary;
		this.icon = icon;
		this.body = body == null ? new JPanel() : body;
		this.refresh = refresh;
		this.open = defaultOpen;

		setBorder(BorderFactory.createCompoundBorder(
				new RoundedBorder(SlayerPrepAssistantPanel.BORDER, SlayerPrepAssistantPanel.CARD_RADIUS),
				BorderFactory.createEmptyBorder(7, 6, 7, 6)));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		JButton header = headerButton();
		header.addActionListener(event ->
		{
			open = !open;
			this.body.setVisible(open);
			header.setText(headerText());
			updateHeight();
			if (this.refresh != null)
			{
				this.refresh.run();
			}
		});
		add(header, BorderLayout.NORTH);
		this.body.setVisible(open);
		add(this.body, BorderLayout.CENTER);
		updateHeight();
	}

	private JButton headerButton()
	{
		JButton button = new JButton(headerText());
		button.setIcon(icon);
		button.setIconTextGap(6);
		button.setForeground(SlayerPrepAssistantPanel.TEXT);
		button.setBackground(SlayerPrepAssistantPanel.PANEL_LIGHT);

		Font baseFont = button.getFont();
		if (baseFont != null)
		{
			button.setFont(baseFont.deriveFont(Font.PLAIN, SlayerPrepAssistantPanel.FONT_SM));
		}

		button.setFocusPainted(false);
		button.setOpaque(true);
		button.setContentAreaFilled(true);
		button.setBorder(headerBorder(SlayerPrepAssistantPanel.BORDER));
		button.setHorizontalAlignment(SwingConstants.LEFT);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				button.setBackground(new Color(35, 35, 32));
				button.setForeground(Color.WHITE);
				button.setBorder(headerBorder(new Color(116, 107, 84)));
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				button.setBackground(SlayerPrepAssistantPanel.PANEL_LIGHT);
				button.setForeground(SlayerPrepAssistantPanel.TEXT);
				button.setBorder(headerBorder(SlayerPrepAssistantPanel.BORDER));
			}
		});

		Dimension prefSize = button.getPreferredSize();
		int prefHeight = prefSize != null ? prefSize.height : 24;
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, prefHeight));
		return button;
	}

	private Border headerBorder(Color color)
	{
		return BorderFactory.createCompoundBorder(
				new RoundedBorder(color, SlayerPrepAssistantPanel.CONTROL_RADIUS),
				BorderFactory.createEmptyBorder(4, 4, 4, 4));
	}

	private String headerText()
	{
		String safeTitle = title == null ? "" : title;
		String safeSummary = summary == null || summary.isEmpty() ? "" : "  " + summary + " ready";
		String arrow = open ? "v" : ">";
		return safeTitle + safeSummary + "  " + arrow;
	}

	void updateHeight()
	{
		revalidate();
		Dimension preferred = getPreferredSize();
		int height = preferred == null ? 0 : preferred.height;
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setMinimumSize(new Dimension(0, height));
	}
}

package com.slayerprepassistant.items;

import com.slayerprepassistant.gear.RecommendedItem;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

public class ItemResolver
{
	private static final Pattern NON_ALPHANUMERIC = Pattern.compile("[^a-z0-9]+");
	private static final Pattern TRAILING_NUMBER = Pattern.compile(" [0-9]+$");
	private static final Pattern DOSE_OR_CHARGE_VARIANT = Pattern.compile(
		".*\\b(potion|brew|restore|serum|mix|antipoison|antidote|antifire|venom|stamina|sanfew|overload|black mask|slayer ring|ring of dueling|games necklace|combat bracelet|skills necklace|amulet of glory)\\b.* [0-9]+$");

	public RecommendedItem resolve(String wikiName)
	{
		return new RecommendedItem(wikiName == null ? "" : wikiName);
	}

	public boolean matches(String recommendedName, Set<String> ownedNames)
	{
		if (ownedNames == null || ownedNames.isEmpty())
		{
			return false;
		}
		String canonicalRecommended = canonicalKey(recommendedName);
		if (canonicalRecommended.isEmpty())
		{
			return false;
		}
		for (String ownedName : ownedNames)
		{
			if (canonicalKey(ownedName).equals(canonicalRecommended))
			{
				return true;
			}
		}
		return false;
	}

	public static String normalize(String value)
	{
		if (value == null)
		{
			return "";
		}
		return NON_ALPHANUMERIC.matcher(value.toLowerCase(Locale.ROOT)).replaceAll(" ").trim();
	}

	public static String canonicalKey(String value)
	{
		String normalized = normalize(value);
		if (normalized.isEmpty())
		{
			return "";
		}

		String canonical = normalized.replace(" helm ", " helmet ");
		if (canonical.startsWith("helm "))
		{
			canonical = "helmet " + canonical.substring("helm ".length());
		}
		if (canonical.endsWith(" helm"))
		{
			canonical = canonical.substring(0, canonical.length() - " helm".length()) + " helmet";
		}

		canonical = removeSuffix(canonical, " i");
		canonical = removeSuffix(canonical, " loaded");
		canonical = removeSuffix(canonical, " empty");
		canonical = removeSuffix(canonical, " ornament kit");
		canonical = removeSuffix(canonical, " ornament");

		return DOSE_OR_CHARGE_VARIANT.matcher(canonical).matches()
			? TRAILING_NUMBER.matcher(canonical).replaceFirst("")
			: canonical;
	}

	public static boolean hasDifferentNumberedVariant(String recommendedName, Set<String> ownedCanonicalNames)
	{
		if (ownedCanonicalNames == null || ownedCanonicalNames.isEmpty())
		{
			return false;
		}
		String recommended = canonicalKey(recommendedName);
		String recommendedBase = numberedVariantBase(recommended);
		if (recommendedBase.equals(recommended))
		{
			return false;
		}
		for (String owned : ownedCanonicalNames)
		{
			if (owned != null && !owned.equals(recommended) && numberedVariantBase(owned).equals(recommendedBase))
			{
				return true;
			}
		}
		return false;
	}

	private static String numberedVariantBase(String canonical)
	{
		return canonical == null ? "" : TRAILING_NUMBER.matcher(canonical).replaceFirst("");
	}

	private static String removeSuffix(String value, String suffix)
	{
		return value.endsWith(suffix) ? value.substring(0, value.length() - suffix.length()).trim() : value;
	}
}

package com.slayerprepassistant.items;

import com.slayerprepassistant.gear.RecommendedItem;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

public class RuneLiteItemLookup
{
	private final ItemManager itemManager;
	private final Map<String, Integer> itemIdCache = new HashMap<>();
	private final Set<String> itemIdMisses = new HashSet<>();

	public RuneLiteItemLookup(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	public synchronized Integer itemId(RecommendedItem item)
	{
		if (item == null || item.getName() == null || item.getName().trim().isEmpty())
		{
			return null;
		}

		String normalized = ItemResolver.normalize(item.getName());
		if (normalized.isEmpty())
		{
			return null;
		}

		Integer cached = itemIdCache.get(normalized);
		if (cached != null)
		{
			return cached;
		}
		if (itemIdMisses.contains(normalized))
		{
			return null;
		}

		for (Integer itemId : item.getItemIds())
		{
			if (itemId != null && itemId > 0)
			{
				itemIdCache.put(normalized, itemId);
				return itemId;
			}
		}

		Integer resolved = findExactItemId(item.getName(), normalized);
		if (resolved != null)
		{
			itemIdCache.put(normalized, resolved);
		}
		return resolved;
	}

	private Integer findExactItemId(String name, String normalized)
	{
		if (itemManager == null)
		{
			return null;
		}
		try
		{
			List<ItemPrice> results = itemManager.search(name);
			if (results != null)
			{
				for (ItemPrice itemPrice : results)
				{
					if (itemPrice != null && itemPrice.getName() != null
						&& ItemResolver.normalize(itemPrice.getName()).equals(normalized))
					{
						return itemPrice.getId();
					}
				}
			}
			itemIdMisses.add(normalized);
		}
		catch (RuntimeException ignored)
		{
			// ItemManager may be unavailable while its price data is still initialising.
			// Do not permanently negative-cache transient failures.
		}
		return null;
	}
}

