package com.slayerprepassistant.readiness;

import com.slayerprepassistant.bank.OwnershipState;
import com.slayerprepassistant.bank.PlayerInventoryState;
import com.slayerprepassistant.gear.GearMatch;
import com.slayerprepassistant.gear.GearMatcher;
import com.slayerprepassistant.gear.LoadoutResult;
import com.slayerprepassistant.gear.RecommendedItem;
import com.slayerprepassistant.guide.InventoryRecommendation;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ReadinessService
{
	private final GearMatcher gearMatcher;

	public ReadinessService()
	{
		this(new GearMatcher());
	}

	public ReadinessService(GearMatcher gearMatcher)
	{
		this.gearMatcher = gearMatcher == null ? new GearMatcher() : gearMatcher;
	}

	public ReadinessResult evaluate(List<InventoryRecommendation> inventory, LoadoutResult loadout)
	{
		return evaluate(inventory, loadout, PlayerInventoryState.unknownBank());
	}

	public ReadinessResult evaluate(List<InventoryRecommendation> inventory, LoadoutResult loadout, PlayerInventoryState playerState)
	{
		int score = 100;
		List<ReadinessIssue> blockers = new ArrayList<>();
		List<ReadinessIssue> warnings = new ArrayList<>();
		List<String> ready = new ArrayList<>();
		List<String> unknown = new ArrayList<>();

		List<GearMatch> gearMatches = loadout == null || loadout.getGearMatches() == null
			? Collections.emptyList()
			: loadout.getGearMatches();
		for (GearMatch match : gearMatches)
		{
			if (match == null || match.getSlot() == null || match.getItem() == null)
			{
				continue;
			}
			OwnershipState state = match.getOwnershipState() == null ? OwnershipState.UNKNOWN : match.getOwnershipState();
			String displayString = match.getSlot().displayName() + ": " + match.getItem().getName();
			if (isReady(state))
			{
				ready.add(displayString);
			}
			else if (state == OwnershipState.MISSING)
			{
				warnings.add(new ReadinessIssue("Missing gear", displayString));
				score -= 10;
			}
			else
			{
				unknown.add(displayString);
				score -= 3;
			}
		}

		PlayerInventoryState effectiveState = playerState == null ? PlayerInventoryState.unknownBank() : playerState;
		for (InventoryRecommendation recommendation : inventory == null ? Collections.<InventoryRecommendation>emptyList() : inventory)
		{
			if (recommendation == null || !recommendation.isRequired())
			{
				continue;
			}
			String itemName = recommendation.getItemOrCategory();
			int requiredQuantity = Math.max(1, recommendation.getMinimumQuantity());
			OwnershipState state = gearMatcher.ownershipForInventoryItem(new RecommendedItem(itemName), effectiveState, requiredQuantity);
			String displayString = requiredQuantity > 1 ? requiredQuantity + " x " + itemName : itemName;
			if (isReady(state))
			{
				ready.add("Inventory: " + displayString);
			}
			else if (state == OwnershipState.MISSING)
			{
				warnings.add(new ReadinessIssue("Missing inventory", displayString));
				score -= 7;
			}
			else
			{
				unknown.add("Inventory: " + displayString);
				score -= 3;
			}
		}

		return new ReadinessResult(Math.max(0, Math.min(100, score)), blockers, warnings, ready, unknown);
	}

	private boolean isReady(OwnershipState state)
	{
		return state == OwnershipState.EQUIPPED || state == OwnershipState.OWNED_IN_INVENTORY || state == OwnershipState.OWNED_IN_BANK;
	}
}

package com.slayerprepassistant;

import java.net.URI;
import java.net.URISyntaxException;
import okhttp3.HttpUrl;

public final class PluginUrls
{
	private static final String OSRS_WIKI_SCHEME = "https";

	public static final String OSRS_WIKI_HOST = "oldschool.runescape.wiki";
	public static final String OSRS_WIKI_BASE_URL = "https://oldschool.runescape.wiki";
	public static final String OSRS_WIKI_API_URL = "https://oldschool.runescape.wiki/api.php";
	public static final String OSRS_WIKI_PAGE_PATH_PREFIX = "/w/";
	public static final String OSRS_WIKI_IMAGE_PATH_PREFIX = "/images/";

	private PluginUrls()
	{
	}

	public static HttpUrl.Builder osrsWikiApiEndpointBuilder()
	{
		return parseDeclaredUrlOrThrow(OSRS_WIKI_API_URL).newBuilder();
	}

	public static String osrsWikiPageUrl(String wikiTitle)
	{
		if (wikiTitle == null || wikiTitle.trim().isEmpty())
		{
			return "";
		}
		try
		{
			String wikiPagePath = OSRS_WIKI_PAGE_PATH_PREFIX + wikiTitle.trim().replace(' ', '_');
			return new URI(OSRS_WIKI_SCHEME, OSRS_WIKI_HOST, wikiPagePath, null)
				.toASCIIString();
		}
		catch (URISyntaxException ex)
		{
			return "";
		}
	}

	public static HttpUrl osrsWikiImageUrlFromMediaWikiSource(String mediaWikiThumbnailSource)
	{
		HttpUrl wikiOwnedSource = parseOnlyIfSourceStillPointsToOsrsWiki(mediaWikiThumbnailSource);
		if (!isOsrsWikiImagePath(wikiOwnedSource))
		{
			return null;
		}

		return rebuildImageUrlFromDeclaredWikiBase(wikiOwnedSource);
	}

	private static boolean isOsrsWikiImagePath(HttpUrl sourceUrl)
	{
		return sourceUrl != null && sourceUrl.encodedPath().startsWith(OSRS_WIKI_IMAGE_PATH_PREFIX);
	}

	private static HttpUrl rebuildImageUrlFromDeclaredWikiBase(HttpUrl wikiOwnedSource)
	{
		HttpUrl.Builder builder = parseDeclaredUrlOrThrow(OSRS_WIKI_BASE_URL)
			.newBuilder()
			.encodedPath(wikiOwnedSource.encodedPath());
		if (wikiOwnedSource.encodedQuery() != null)
		{
			builder.encodedQuery(wikiOwnedSource.encodedQuery());
		}
		return builder.build();
	}

	private static HttpUrl parseOnlyIfSourceStillPointsToOsrsWiki(String mediaWikiThumbnailSource)
	{
		if (mediaWikiThumbnailSource == null || mediaWikiThumbnailSource.trim().isEmpty())
		{
			return null;
		}

		String normalizedSource = mediaWikiThumbnailSource.trim();
		if (normalizedSource.startsWith(OSRS_WIKI_IMAGE_PATH_PREFIX))
		{
			return parseDeclaredUrlOrThrow(OSRS_WIKI_BASE_URL).resolve(normalizedSource);
		}
		if (normalizedSource.startsWith("//"))
		{
			normalizedSource = OSRS_WIKI_SCHEME + ":" + normalizedSource;
		}

		HttpUrl parsedSource = HttpUrl.parse(normalizedSource);
		if (parsedSource == null || !OSRS_WIKI_HOST.equalsIgnoreCase(parsedSource.host()))
		{
			return null;
		}
		return parsedSource;
	}

	private static HttpUrl parseDeclaredUrlOrThrow(String declaredUrl)
	{
		HttpUrl parsed = HttpUrl.parse(declaredUrl);
		if (parsed == null)
		{
			throw new IllegalStateException("Invalid plugin URL: " + declaredUrl);
		}
		return parsed;
	}
}

