import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("slayer-prep-assistant")
public interface SlayerPrepAssistantConfig extends Config
{
	@ConfigItem(
		keyName = "useWikiStrategyData",
		name = "Use Wiki strategy data",
		description = "Retrieve public strategy guides from the Old School RuneScape Wiki",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean useWikiStrategyData()
	{
		return false;
	}
}

package com.slayerprepassistant.wiki;

import java.util.Objects;

public class WikiResponse
{
	private final WikiState state;
	private final WikiRevision revision;
	private final String message;

	public WikiResponse(WikiState state, WikiRevision revision, String message)
	{
		this.state = Objects.requireNonNullElse(state, WikiState.ERROR);
		this.revision = revision;
		this.message = message == null ? "" : message;
	}

	public WikiState getState()
	{
		return state;
	}

	public WikiRevision getRevision()
	{
		return revision;
	}

	public String getMessage()
	{
		return message;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		WikiResponse that = (WikiResponse) o;
		return state == that.state &&
				Objects.equals(revision, that.revision) &&
				message.equals(that.message);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(state, revision, message);
	}

	@Override
	public String toString()
	{
		return "WikiResponse{state=" + state + ", message='" + message + "'}";
	}
}

package com.slayerprepassistant.wiki;

import java.awt.image.BufferedImage;
import java.util.Objects;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

public class WikiImageService
{
	private final WikiClient wikiClient;
	private final BooleanSupplier enabled;

	public WikiImageService(WikiClient wikiClient, BooleanSupplier enabled)
	{
		this.wikiClient = Objects.requireNonNull(wikiClient, "wikiClient cannot be null");
		this.enabled = Objects.requireNonNull(enabled, "enabled cannot be null");
	}

	public void load(String title, int size, Consumer<BufferedImage> callback)
	{
		if (callback == null)
		{
			return;
		}
		if (!enabled.getAsBoolean() || title == null || title.trim().isEmpty() || size <= 0)
		{
			callback.accept(null);
			return;
		}
		wikiClient.fetchPageImage(title.trim(), size, callback);
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.gear.GearRecommendation;
import com.slayerprepassistant.gear.GearSlot;
import com.slayerprepassistant.gear.GearTier;
import com.slayerprepassistant.gear.RecommendedItem;
import com.slayerprepassistant.guide.CombatMethod;
import com.slayerprepassistant.guide.InventoryRecommendation;
import com.slayerprepassistant.guide.MonsterGuide;
import com.slayerprepassistant.guide.StrategyMethod;
import com.slayerprepassistant.model.ParsingConfidence;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class WikiStrategyParser
{
	private static final Pattern WIKI_HEADING = Pattern.compile("^=+\\s*(.+?)\\s*=+$");
	private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[([^\\]|#]+)(?:#[^\\]|]+)?(?:\\|([^\\]]+))?\\]\\]");
	private static final Pattern TEMPLATE_LINK = Pattern.compile("\\{\\{\\s*[Pp]linkp?\\s*\\|\\s*([^\\}|]+)(?:\\|[^\\}]*)?\\}\\}");
	private static final Pattern STYLE_PARAMETER = Pattern.compile("^\\|\\s*style\\s*=\\s*(.+)$", Pattern.CASE_INSENSITIVE);
	private final RenderedStrategyParser renderedStrategyParser = new RenderedStrategyParser();

	public WikiParsingResult parse(String monsterName, String wikiTitle, String wikiUrl, long revisionId, String text)
	{
		String safeText = text == null ? "" : text;
		String safeMonsterName = Objects.requireNonNullElse(monsterName, "");
		String safeWikiTitle = Objects.requireNonNullElse(wikiTitle, "");
		String safeWikiUrl = Objects.requireNonNullElse(wikiUrl, "");

		List<String> warnings = new ArrayList<>();
		Map<CombatMethod, List<String>> methodLines = new EnumMap<>(CombatMethod.class);
		for (CombatMethod method : CombatMethod.values())
		{
			methodLines.put(method, new ArrayList<>());
		}
		List<InventoryRecommendation> sharedInventory = new ArrayList<>();
		Map<CombatMethod, List<InventoryRecommendation>> methodInventory = new EnumMap<>(CombatMethod.class);
		for (CombatMethod method : CombatMethod.values())
		{
			methodInventory.put(method, new ArrayList<>());
		}
		List<String> notes = new ArrayList<>();
		List<MonsterVariant> variants = new ArrayList<>();
		List<CombatMethod> methodOrder = new ArrayList<>();
		List<String> inventoryTemplateLines = new ArrayList<>();
		CombatMethod inventoryTemplateMethod = CombatMethod.defaultMethod();
		boolean collectingInventoryTemplate = false;

		String section = "general";
		CombatMethod currentMethod = CombatMethod.defaultMethod();
		for (String rawLine : safeText.split("\\R"))
		{
			String line = rawLine.trim();
			if (line.isEmpty())
			{
				continue;
			}
			if (collectingInventoryTemplate)
			{
				inventoryTemplateLines.add(line);
				if (isTemplateEnd(line))
				{
					methodInventory.get(inventoryTemplateMethod).addAll(parseInventoryTemplate(inventoryTemplateLines));
					inventoryTemplateLines.clear();
					collectingInventoryTemplate = false;
				}
				continue;
			}
			String heading = heading(line);
			if (heading != null)
			{
				String normalizedHeading = heading.toLowerCase(Locale.ROOT);
				section = categorize(normalizedHeading);
				CombatMethod headingMethod = methodForHeading(normalizedHeading);
				if (headingMethod != null)
				{
					currentMethod = headingMethod;
					rememberMethod(methodOrder, currentMethod);
				}
				continue;
			}
			CombatMethod tabberMethod = methodForTabberLine(line);
			if (tabberMethod != null)
			{
				currentMethod = tabberMethod;
				rememberMethod(methodOrder, currentMethod);
				section = "equipment";
				continue;
			}
			CombatMethod templateStyleMethod = methodForTemplateStyle(line);
			if (templateStyleMethod != null && ("equipment".equals(section) || "method".equals(section)))
			{
				currentMethod = templateStyleMethod;
				rememberMethod(methodOrder, currentMethod);
				section = "equipment";
				continue;
			}
			if (isInventoryTemplateStart(line))
			{
				inventoryTemplateMethod = currentMethod;
				inventoryTemplateLines.add(line);
				if (isTemplateEnd(line))
				{
					methodInventory.get(inventoryTemplateMethod).addAll(parseInventoryTemplate(inventoryTemplateLines));
					inventoryTemplateLines.clear();
				}
				else
				{
					collectingInventoryTemplate = true;
				}
				continue;
			}
			if ("variants".equals(section))
			{
				parseVariants(line, variants);
			}
			else if ("inventory".equals(section))
			{
				sharedInventory.add(new InventoryRecommendation(stripBullet(line), 0, true));
			}
			else if ("equipment".equals(section) || "method".equals(section))
			{
				methodLines.get(currentMethod).add(stripBullet(line));
			}
			else
			{
				notes.add(stripBullet(line));
			}
		}

		List<StrategyMethod> methods = new ArrayList<>();
		for (CombatMethod method : methodOrder)
		{
			List<GearRecommendation> gear = parseGear(methodLines.get(method));
			if (!gear.isEmpty())
			{
				methods.add(new StrategyMethod(method, gear, inventoryForMethod(method, methodInventory, sharedInventory), notes, ParsingConfidence.MEDIUM));
			}
		}
		for (Map.Entry<CombatMethod, List<String>> entry : methodLines.entrySet())
		{
			if (methodOrder.contains(entry.getKey()))
			{
				continue;
			}
			List<GearRecommendation> gear = parseGear(entry.getValue());
			if (!gear.isEmpty())
			{
				methods.add(new StrategyMethod(entry.getKey(), gear, inventoryForMethod(entry.getKey(), methodInventory, sharedInventory), notes, ParsingConfidence.MEDIUM));
			}
		}
		if (methods.isEmpty())
		{
			warnings.add("No combat method sections were parsed.");
		}

		MonsterGuide guide = new MonsterGuide(safeMonsterName, safeWikiTitle, safeWikiUrl, revisionId, Instant.now(), methods, notes, warnings.isEmpty() ? ParsingConfidence.MEDIUM : ParsingConfidence.LOW);
		return new WikiParsingResult(guide, variants, warnings);
	}

	public WikiParsingResult mergeRenderedHtml(WikiParsingResult source, String renderedHtml)
	{
		return renderedStrategyParser.mergeInto(source, renderedHtml);
	}

	private List<InventoryRecommendation> inventoryForMethod(CombatMethod method, Map<CombatMethod, List<InventoryRecommendation>> methodInventory, List<InventoryRecommendation> sharedInventory)
	{
		List<InventoryRecommendation> inventory = methodInventory.get(method);
		return inventory == null || inventory.isEmpty() ? sharedInventory : inventory;
	}

	private boolean isInventoryTemplateStart(String line)
	{
		return line != null && line.toLowerCase(Locale.ROOT).startsWith("{{inventory");
	}

	private boolean isTemplateEnd(String line)
	{
		return line != null && (line.trim().equals("}}") || line.trim().endsWith("}}"));
	}

	private List<InventoryRecommendation> parseInventoryTemplate(List<String> lines)
	{
		if (lines == null || lines.isEmpty())
		{
			return Collections.emptyList();
		}
		String block = String.join("\n", lines);
		int start = block.toLowerCase(Locale.ROOT).indexOf("{{inventory");
		if (start < 0)
		{
			return Collections.emptyList();
		}
		int end = block.lastIndexOf("}}");
		String content = end > start
				? block.substring(start + "{{Inventory".length(), end)
				: block.substring(start + "{{Inventory".length());
		Map<String, Integer> counts = new LinkedHashMap<>();
		for (String parameter : splitTemplateParameters(content))
		{
			String itemName = inventoryTemplateItem(parameter);
			if (!itemName.isEmpty())
			{
				counts.merge(itemName, 1, Integer::sum);
			}
		}
		List<InventoryRecommendation> inventory = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : counts.entrySet())
		{
			inventory.add(new InventoryRecommendation(entry.getKey(), entry.getValue(), true));
		}
		return inventory;
	}

	private List<String> splitTemplateParameters(String content)
	{
		if (content == null)
		{
			return Collections.emptyList();
		}
		List<String> parameters = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		int templateDepth = 0;
		int linkDepth = 0;
		for (int i = 0; i < content.length(); i++)
		{
			char character = content.charAt(i);
			char next = i + 1 < content.length() ? content.charAt(i + 1) : 0;
			if (character == '{' && next == '{')
			{
				templateDepth++;
				current.append(character).append(next);
				i++;
				continue;
			}
			if (character == '}' && next == '}')
			{
				templateDepth = Math.max(0, templateDepth - 1);
				current.append(character).append(next);
				i++;
				continue;
			}
			if (character == '[' && next == '[')
			{
				linkDepth++;
				current.append(character).append(next);
				i++;
				continue;
			}
			if (character == ']' && next == ']')
			{
				linkDepth = Math.max(0, linkDepth - 1);
				current.append(character).append(next);
				i++;
				continue;
			}
			if (character == '|' && templateDepth == 0 && linkDepth == 0)
			{
				parameters.add(current.toString());
				current.setLength(0);
				continue;
			}
			current.append(character);
		}
		parameters.add(current.toString());
		return parameters;
	}

	private String inventoryTemplateItem(String parameter)
	{
		String value = parameter == null ? "" : parameter.trim();
		if (value.isEmpty())
		{
			return "";
		}
		int equals = value.indexOf('=');
		if (equals >= 0)
		{
			String key = value.substring(0, equals).trim().toLowerCase(Locale.ROOT);
			String assignedValue = value.substring(equals + 1).trim();
			if (key.matches("\\d+"))
			{
				value = assignedValue;
			}
			else if ("align".equals(key) || "caption".equals(key) || "name".equals(key) || "style".equals(key))
			{
				return "";
			}
		}
		return cleanItemName(value);
	}

	private String categorize(String heading)
	{
		if (heading == null)
		{
			return "general";
		}
		if (heading.contains("monster variant"))
		{
			return "variants";
		}
		if (heading.contains("inventory") || heading.contains("supplies"))
		{
			return "inventory";
		}
		if (heading.contains("equipment") || heading.contains("gear") || heading.contains("melee") || heading.contains("ranged") || heading.contains("magic"))
		{
			return "equipment";
		}
		return "general";
	}

	private CombatMethod methodForHeading(String heading)
	{
		if (heading == null)
		{
			return null;
		}
		if (heading.contains("melee"))
		{
			return CombatMethod.MELEE;
		}
		if (heading.contains("ranged") || heading.contains("range"))
		{
			return CombatMethod.RANGED;
		}
		if (heading.contains("magic") || heading.contains("mage"))
		{
			return CombatMethod.MAGIC;
		}
		return null;
	}

	private void rememberMethod(List<CombatMethod> methodOrder, CombatMethod method)
	{
		if (method != null && !methodOrder.contains(method))
		{
			methodOrder.add(method);
		}
	}

	private CombatMethod methodForTabberLine(String line)
	{
		if (line == null)
		{
			return null;
		}

		String normalized = line.trim();
		if (normalized.startsWith("|-|"))
		{
			normalized = normalized.substring(3).trim();
		}
		int equals = normalized.indexOf('=');
		if (equals < 0)
		{
			return null;
		}

		String label = normalized.substring(0, equals).trim();
		if (label.isEmpty() || label.indexOf('|') >= 0)
		{
			return null;
		}
		return methodForHeading(label.toLowerCase(Locale.ROOT));
	}

	private CombatMethod methodForTemplateStyle(String line)
	{
		if (line == null)
		{
			return null;
		}
		Matcher matcher = STYLE_PARAMETER.matcher(line.trim());
		if (!matcher.matches())
		{
			return null;
		}
		return methodForHeading(cleanItemName(matcher.group(1)).toLowerCase(Locale.ROOT));
	}

	private void parseVariants(String line, List<MonsterVariant> variants)
	{
		if (line == null || variants == null)
		{
			return;
		}
		Matcher matcher = WIKI_LINK.matcher(line);
		while (matcher.find())
		{
			String pageTitle = matcher.group(1).trim();
			if (pageTitle.isEmpty() || pageTitle.contains(":"))
			{
				continue;
			}
			String displayName = matcher.group(2) == null ? pageTitle : matcher.group(2).trim();
			if (displayName.isEmpty() || displayName.matches("\\d+"))
			{
				continue;
			}
			String wikiUrl = WikiTitles.pageUrl(pageTitle);
			boolean alreadyPresent = variants.stream().anyMatch(variant -> variant.getWikiPageTitle().equalsIgnoreCase(pageTitle));
			if (!alreadyPresent)
			{
				variants.add(new MonsterVariant(displayName, pageTitle, wikiUrl));
			}
		}
	}

	private String heading(String line)
	{
		if (line == null)
		{
			return null;
		}
		if (line.startsWith("#"))
		{
			return line.replace("#", "").trim();
		}
		Matcher matcher = WIKI_HEADING.matcher(line);
		return matcher.matches() ? matcher.group(1).trim() : null;
	}

	private List<GearRecommendation> parseGear(List<String> lines)
	{
		if (lines == null || lines.isEmpty())
		{
			return Collections.emptyList();
		}
		Map<GearSlot, List<GearTier>> tiersBySlot = new EnumMap<>(GearSlot.class);
		for (String line : lines)
		{
			if (line == null || line.trim().isEmpty())
			{
				continue;
			}
			String[] slotSplit = line.split("[:=]", 2);
			if (slotSplit.length != 2)
			{
				continue;
			}
			GearSlot slot = WikiGearSlots.parse(slotSplit[0]);
			if (slot == null)
			{
				continue;
			}
			Integer templateRank = WikiGearSlots.templateRank(slotSplit[0]);
			String[] tierParts = tierParts(slotSplit[1]);
			for (int i = 0; i < tierParts.length; i++)
			{
				String[] alternatives = tierParts[i].split("/");
				List<RecommendedItem> items = new ArrayList<>();
				for (String alternative : alternatives)
				{
					for (String name : itemNamesFromAlternative(alternative))
					{
						if (!name.isEmpty())
						{
							items.add(new RecommendedItem(name));
						}
					}
				}
				if (!items.isEmpty())
				{
					int priority = templateRank == null ? i + 1 : templateRank + i;
					tiersBySlot.computeIfAbsent(slot, ignored -> new ArrayList<>()).add(new GearTier(priority, items));
				}
			}
		}
		List<GearRecommendation> recommendations = new ArrayList<>();
		for (Map.Entry<GearSlot, List<GearTier>> entry : tiersBySlot.entrySet())
		{
			entry.getValue().sort(java.util.Comparator.comparingInt(GearTier::getPriority));
			recommendations.add(new GearRecommendation(entry.getKey(), entry.getValue()));
		}
		return recommendations;
	}

	private String[] tierParts(String value)
	{
		String normalized = value == null ? "" : value.replaceAll("(?i)<br\\s*/?>", "/");
		return normalized.split("\\s*>\\s*/?\\s*");
	}

	private List<String> itemNamesFromAlternative(String alternative)
	{
		if (alternative == null || alternative.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> names = new ArrayList<>();
		Matcher templateMatcher = TEMPLATE_LINK.matcher(alternative);
		while (templateMatcher.find())
		{
			String name = cleanItemName(templateMatcher.group(1));
			if (!name.isEmpty() && names.stream().noneMatch(existing -> existing.equalsIgnoreCase(name)))
			{
				names.add(name);
			}
		}
		if (!names.isEmpty())
		{
			return names;
		}
		String name = cleanItemName(alternative);
		return name.isEmpty() ? Collections.emptyList() : Collections.singletonList(name);
	}

	private String stripBullet(String line)
	{
		return line == null ? "" : line.replaceFirst("^[*\\-]+\\s*", "").trim();
	}

	private String cleanItemName(String value)
	{
		if (value == null)
		{
			return "";
		}
		String cleaned = stripBullet(value)
				.replaceAll("(?i)<br\\s*/?>", " ")
				.replaceAll("\\{\\{efn[^}]*}}", "")
				.replaceAll("\\[\\[[^\\]|]+\\|([^\\]]+)]]", "$1")
				.replaceAll("\\[\\[([^\\]]+)]]", "$1")
				.replaceAll("''+", "")
				.trim();
		Matcher templateMatcher = TEMPLATE_LINK.matcher(cleaned);
		if (templateMatcher.find())
		{
			cleaned = templateMatcher.group(1).trim();
		}
		cleaned = cleaned.replaceAll("\\{\\{[^|}]+\\|([^}|]+)(?:\\|[^}]*)?}}", "$1")
				.replaceAll("\\{\\{[^}]+}}", "")
				.replaceAll("\\([^)]*if on a[^)]*\\)", "")
				.replaceAll("\\s+", " ")
				.trim();
		return cleaned.matches("(?i)n/?a|none|-") ? "" : cleaned;
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.guide.MonsterGuide;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class WikiParsingResult
{
	private final MonsterGuide guide;
	private final List<MonsterVariant> variants;
	private final List<String> warnings;

	public WikiParsingResult(MonsterGuide guide, List<MonsterVariant> variants, List<String> warnings)
	{
		this.guide = guide;
		this.variants = Collections.unmodifiableList(variants == null ? Collections.emptyList() : new ArrayList<>(variants));
		this.warnings = Collections.unmodifiableList(warnings == null ? Collections.emptyList() : new ArrayList<>(warnings));
	}

	public MonsterGuide getGuide()
	{
		return guide;
	}

	public List<MonsterVariant> getVariants()
	{
		return variants;
	}

	public List<String> getWarnings()
	{
		return warnings;
	}
}

package com.slayerprepassistant.wiki;

import java.time.Instant;
import java.util.Objects;

public class WikiRevision
{
	private final String title;
	private final long revisionId;
	private final Instant fetchedAt;
	private final String text;

	public WikiRevision(String title, long revisionId, Instant fetchedAt, String text)
	{
		this.title = title == null ? "" : title;
		this.revisionId = revisionId;
		this.fetchedAt = fetchedAt == null ? Instant.now() : fetchedAt;
		this.text = text == null ? "" : text;
	}

	public String getTitle()
	{
		return title;
	}

	public long getRevisionId()
	{
		return revisionId;
	}

	public String getText()
	{
		return text;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		WikiRevision that = (WikiRevision) o;
		return revisionId == that.revisionId &&
				title.equals(that.title) &&
				fetchedAt.equals(that.fetchedAt) &&
				text.equals(that.text);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(title, revisionId, fetchedAt, text);
	}

	@Override
	public String toString()
	{
		return "WikiRevision{title='" + title + "', revisionId=" + revisionId + "}";
	}
}

package com.slayerprepassistant.wiki;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class WikiApiResponseParser
{
	private final Gson gson;

	WikiApiResponseParser(Gson gson)
	{
		this.gson = gson;
	}

	WikiResponse parseRevision(String fallbackTitle, String json)
	{
		Map<String, WikiResponse> responses = parseRevisions(Collections.singletonList(fallbackTitle), json);
		return responses.getOrDefault(
			WikiTitles.cacheKey(fallbackTitle),
			new WikiResponse(WikiState.ERROR, null, "Unable to parse Wiki response"));
	}

	Map<String, WikiResponse> parseRevisions(List<String> requestedTitles, String json)
	{
		Map<String, WikiResponse> result = new LinkedHashMap<>();
		if (requestedTitles == null || requestedTitles.isEmpty())
		{
			return result;
		}
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			JsonObject query = root == null ? null : root.getAsJsonObject("query");
			JsonObject pages = query == null ? null : query.getAsJsonObject("pages");
			if (pages == null)
			{
				return errorsFor(requestedTitles, "Wiki page not found");
			}

			Map<String, String> aliases = new HashMap<>();
			collectAliases(query, "normalized", aliases);
			collectAliases(query, "redirects", aliases);

			Map<String, WikiResponse> responsesByTitle = new HashMap<>();
			for (Map.Entry<String, JsonElement> entry : pages.entrySet())
			{
				JsonObject page = entry.getValue() == null || !entry.getValue().isJsonObject()
					? null
					: entry.getValue().getAsJsonObject();
				if (page == null)
				{
					continue;
				}
				String title = page.has("title") ? page.get("title").getAsString() : "";
				responsesByTitle.put(WikiTitles.cacheKey(title), parseRevisionPage(title, page));
			}

			for (String requestedTitle : requestedTitles)
			{
				String requestedKey = WikiTitles.cacheKey(requestedTitle);
				String resolvedKey = resolveAlias(requestedKey, aliases);
				WikiResponse response = responsesByTitle.get(resolvedKey);
				if (response == null)
				{
					response = responsesByTitle.get(requestedKey);
				}
				result.put(requestedKey, response == null
					? new WikiResponse(WikiState.ERROR, null, "Wiki page not found")
					: response);
			}
			return result;
		}
		catch (RuntimeException ex)
		{
			return errorsFor(requestedTitles, "Unable to parse Wiki response");
		}
	}

	WikiResponse parseRendered(String fallbackTitle, String json)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			JsonObject parse = root == null ? null : root.getAsJsonObject("parse");
			if (parse == null)
			{
				return new WikiResponse(WikiState.ERROR, null, "Wiki page not found");
			}
			String title = parse.has("title") ? parse.get("title").getAsString() : fallbackTitle;
			long revisionId = parse.has("revid") ? parse.get("revid").getAsLong() : 0;
			JsonObject text = parse.getAsJsonObject("text");
			JsonElement html = text == null ? null : text.get("*");
			return html == null
				? new WikiResponse(WikiState.ERROR, null, "Wiki rendered HTML not found")
				: new WikiResponse(WikiState.READY, new WikiRevision(title, revisionId, Instant.now(), html.getAsString()), "");
		}
		catch (RuntimeException ex)
		{
			return new WikiResponse(WikiState.ERROR, null, "Unable to parse Wiki response");
		}
	}

	Map<String, String> pageImageSources(List<String> requestedTitles, String json)
	{
		Map<String, String> result = new LinkedHashMap<>();
		if (requestedTitles == null || requestedTitles.isEmpty())
		{
			return result;
		}
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			JsonObject query = root == null ? null : root.getAsJsonObject("query");
			JsonObject pages = query == null ? null : query.getAsJsonObject("pages");
			if (pages == null)
			{
				return emptyImageResults(requestedTitles);
			}

			Map<String, String> aliases = new HashMap<>();
			collectAliases(query, "normalized", aliases);
			collectAliases(query, "redirects", aliases);
			Map<String, String> imageSourcesByTitle = new HashMap<>();
			for (Map.Entry<String, JsonElement> entry : pages.entrySet())
			{
				JsonElement value = entry.getValue();
				if (value == null || !value.isJsonObject())
				{
					continue;
				}
				JsonObject page = value.getAsJsonObject();
				String pageTitle = page.has("title") ? page.get("title").getAsString() : "";
				JsonObject thumbnail = page.getAsJsonObject("thumbnail");
				String imageSource = thumbnail != null && thumbnail.has("source") ? thumbnail.get("source").getAsString() : "";
				imageSourcesByTitle.put(WikiTitles.cacheKey(pageTitle), imageSource);
			}

			for (String requestedTitle : requestedTitles)
			{
				String requestedKey = WikiTitles.cacheKey(requestedTitle);
				String resolvedKey = resolveAlias(requestedKey, aliases);
				result.put(requestedKey, imageSourcesByTitle.getOrDefault(resolvedKey, imageSourcesByTitle.getOrDefault(requestedKey, "")));
			}
			return result;
		}
		catch (RuntimeException ex)
		{
			return emptyImageResults(requestedTitles);
		}
	}

	private Map<String, String> emptyImageResults(List<String> requestedTitles)
	{
		Map<String, String> empty = new LinkedHashMap<>();
		for (String title : requestedTitles)
		{
			empty.put(WikiTitles.cacheKey(title), "");
		}
		return empty;
	}

	private WikiResponse parseRevisionPage(String fallbackTitle, JsonObject page)
	{
		if (page.has("missing"))
		{
			return new WikiResponse(WikiState.ERROR, null, "Wiki page not found");
		}
		String title = page.has("title") ? page.get("title").getAsString() : fallbackTitle;
		JsonArray revisions = page.getAsJsonArray("revisions");
		if (revisions == null || revisions.size() == 0)
		{
			return new WikiResponse(WikiState.ERROR, null, "Wiki revision not found");
		}
		JsonObject revision = revisions.get(0).getAsJsonObject();
		long revisionId = revision.has("revid") ? revision.get("revid").getAsLong() : 0;
		return new WikiResponse(WikiState.READY, new WikiRevision(title, revisionId, Instant.now(), revisionText(revision)), "");
	}

	private void collectAliases(JsonObject query, String member, Map<String, String> aliases)
	{
		JsonArray array = query.getAsJsonArray(member);
		if (array == null)
		{
			return;
		}
		for (JsonElement element : array)
		{
			if (element == null || !element.isJsonObject())
			{
				continue;
			}
			JsonObject alias = element.getAsJsonObject();
			if (alias.has("from") && alias.has("to"))
			{
				aliases.put(WikiTitles.cacheKey(alias.get("from").getAsString()), WikiTitles.cacheKey(alias.get("to").getAsString()));
			}
		}
	}

	private String resolveAlias(String key, Map<String, String> aliases)
	{
		String current = key;
		for (int i = 0; i <= aliases.size(); i++)
		{
			String next = aliases.get(current);
			if (next == null || next.equals(current))
			{
				return current;
			}
			current = next;
		}
		return current;
	}

	private Map<String, WikiResponse> errorsFor(List<String> requestedTitles, String message)
	{
		Map<String, WikiResponse> errors = new LinkedHashMap<>();
		for (String title : requestedTitles)
		{
			errors.put(WikiTitles.cacheKey(title), new WikiResponse(WikiState.ERROR, null, message));
		}
		return errors;
	}

	private String revisionText(JsonObject revision)
	{
		JsonObject slots = revision.getAsJsonObject("slots");
		JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
		JsonElement text = main == null ? revision.get("*") : main.get("*");
		if (text == null && main != null)
		{
			text = main.get("content");
		}
		return text == null ? "" : text.getAsString();
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.gear.GearSlot;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class WikiGearSlots
{
	private static final Pattern SLOT_RANK = Pattern.compile("^\\|?\\s*[A-Za-z ]+(\\d+)\\s*$");

	private WikiGearSlots()
	{
	}

	static GearSlot parse(String value)
	{
		String normalized = value.trim()
			.replaceFirst("^\\|", "")
			.replaceFirst("\\d+$", "")
			.trim()
			.toUpperCase(Locale.ROOT)
			.replace(' ', '_');
		if ("TORSO".equals(normalized))
		{
			normalized = "BODY";
		}
		if ("AMMUNITION".equals(normalized))
		{
			normalized = "AMMO";
		}
		if ("AMMO2".equals(normalized))
		{
			normalized = "AMMO";
		}
		if ("GLOVES".equals(normalized))
		{
			normalized = "HANDS";
		}
		if ("BOOTS".equals(normalized))
		{
			normalized = "FEET";
		}
		try
		{
			return GearSlot.valueOf(normalized);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	static Integer templateRank(String slotKey)
	{
		Matcher matcher = SLOT_RANK.matcher(slotKey == null ? "" : slotKey.trim());
		return matcher.matches() ? Integer.parseInt(matcher.group(1)) : null;
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.PluginUrls;
import com.slayerprepassistant.items.ItemResolver;
import java.util.Locale;

public final class WikiTitles
{
	private WikiTitles()
	{
	}

	public static String pageUrl(String title)
	{
		if (title == null || title.trim().isEmpty())
		{
			return "";
		}
		return PluginUrls.osrsWikiPageUrl(title);
	}

	public static String singularTitle(String title)
	{
		if (title == null || title.trim().isEmpty())
		{
			return "";
		}
		String trimmed = title.trim();
		return trimmed.length() > 3 && trimmed.endsWith("s") ? trimmed.substring(0, trimmed.length() - 1) : trimmed;
	}

	public static String wikiTitle(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			return "";
		}
		String normalized = ItemResolver.normalize(input);
		if (normalized.isEmpty())
		{
			return input.trim();
		}
		return normalized.substring(0, 1).toUpperCase(Locale.ROOT) + normalized.substring(1);
	}

	public static String cacheKey(String title)
	{
		return title == null ? "" : title.trim().toLowerCase(Locale.ROOT);
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.task.TargetOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public class WikiSetupLoader
{
	private static final int PARSED_CACHE_SIZE = 128;

	private final WikiClient wikiClient;
	private final WikiStrategyParser wikiStrategyParser;
	private final java.util.function.Consumer<Runnable> clientThreadInvoker;
	private final Map<String, WikiParsingResult> wikiResultCache = Collections.synchronizedMap(
		new LinkedHashMap<String, WikiParsingResult>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, WikiParsingResult> eldest)
			{
				return size() > PARSED_CACHE_SIZE;
			}
		});

	public WikiSetupLoader(WikiClient wikiClient, WikiStrategyParser wikiStrategyParser, java.util.function.Consumer<Runnable> clientThreadInvoker)
	{
		this.wikiClient = Objects.requireNonNull(wikiClient, "wikiClient cannot be null");
		this.wikiStrategyParser = Objects.requireNonNull(wikiStrategyParser, "wikiStrategyParser cannot be null");
		this.clientThreadInvoker = Objects.requireNonNull(clientThreadInvoker, "clientThreadInvoker cannot be null");
	}

	public void loadStrategy(int requestId, TargetOption target, List<String> candidates, StaleCheck staleCheck, StrategyHandler handler, Runnable exhausted)
	{
		loadStrategy(requestId, target, target, candidates, staleCheck, handler, exhausted);
	}

	/**
	 * Loads the first usable strategy for {@code parseTarget} while staleness is checked against
	 * {@code staleTarget}. Candidate revision texts are fetched in a single MediaWiki batch request.
	 */
	public void loadStrategy(
		int requestId,
		TargetOption staleTarget,
		TargetOption parseTarget,
		List<String> candidates,
		StaleCheck staleCheck,
		StrategyHandler handler,
		Runnable exhausted)
	{
		List<String> safeCandidates = safeCandidates(candidates);
		Runnable safeExhausted = safeRunnable(exhausted);
		if (safeCandidates.isEmpty())
		{
			safeExhausted.run();
			return;
		}
		if (isStale(staleCheck, requestId, staleTarget))
		{
			return;
		}

		Map<String, WikiParsingResult> cached = cachedResults(safeCandidates);
		if (cached.size() == safeCandidates.size())
		{
			continueStrategy(requestId, staleTarget, safeCandidates, cached, 0, staleCheck, handler, safeExhausted);
			return;
		}

		List<String> uncached = new ArrayList<>();
		for (String title : safeCandidates)
		{
			if (!cached.containsKey(WikiTitles.cacheKey(title)))
			{
				uncached.add(title);
			}
		}

		wikiClient.fetchRevisionTexts(uncached, responses -> wikiClient.executeAsync(() ->
		{
			Map<String, WikiParsingResult> parsed = new LinkedHashMap<>(cached);
			for (String title : uncached)
			{
				WikiResponse response = responses.get(WikiTitles.cacheKey(title));
				if (isReady(response))
				{
					parsed.put(WikiTitles.cacheKey(title), parse(parseTarget, response));
				}
			}
			clientThreadInvoker.accept(() ->
			{
				if (!isStale(staleCheck, requestId, staleTarget))
				{
					continueStrategy(requestId, staleTarget, safeCandidates, parsed, 0, staleCheck, handler, safeExhausted);
				}
			});
		}));
	}

	public void loadVariantPage(int requestId, TargetOption target, List<String> candidates, StaleCheck staleCheck, VariantHandler handler, Runnable exhausted)
	{
		List<String> safeCandidates = safeCandidates(candidates);
		Runnable safeExhausted = safeRunnable(exhausted);
		if (safeCandidates.isEmpty())
		{
			safeExhausted.run();
			return;
		}
		if (isStale(staleCheck, requestId, target))
		{
			return;
		}

		Map<String, WikiParsingResult> cached = cachedResults(safeCandidates);
		if (cached.size() == safeCandidates.size())
		{
			continueVariantPage(requestId, target, safeCandidates, cached, 0, staleCheck, handler, safeExhausted);
			return;
		}

		List<String> uncached = new ArrayList<>();
		for (String title : safeCandidates)
		{
			if (!cached.containsKey(WikiTitles.cacheKey(title)))
			{
				uncached.add(title);
			}
		}
		wikiClient.fetchRevisionTexts(uncached, responses -> wikiClient.executeAsync(() ->
		{
			Map<String, WikiParsingResult> parsed = new LinkedHashMap<>(cached);
			for (String title : uncached)
			{
				WikiResponse response = responses.get(WikiTitles.cacheKey(title));
				if (isReady(response))
				{
					WikiParsingResult result = parse(target, response);
					parsed.put(WikiTitles.cacheKey(title), result);
					cache(title, result);
				}
			}
			clientThreadInvoker.accept(() ->
			{
				if (!isStale(staleCheck, requestId, target))
				{
					continueVariantPage(requestId, target, safeCandidates, parsed, 0, staleCheck, handler, safeExhausted);
				}
			});
		}));
	}

	private void continueStrategy(
		int requestId,
		TargetOption staleTarget,
		List<String> candidates,
		Map<String, WikiParsingResult> parsedByTitle,
		int index,
		StaleCheck staleCheck,
		StrategyHandler handler,
		Runnable exhausted)
	{
		if (isStale(staleCheck, requestId, staleTarget))
		{
			return;
		}
		if (index >= candidates.size())
		{
			exhausted.run();
			return;
		}

		String title = candidates.get(index);
		String key = WikiTitles.cacheKey(title);
		WikiParsingResult cached = cachedResult(key);
		if (cached != null)
		{
			handleStrategyResult(requestId, staleTarget, candidates, parsedByTitle, index, staleCheck, handler, exhausted, cached);
			return;
		}

		WikiParsingResult parsed = parsedByTitle.get(key);
		if (parsed == null || parsed.getGuide() == null)
		{
			continueStrategy(requestId, staleTarget, candidates, parsedByTitle, index + 1, staleCheck, handler, exhausted);
			return;
		}

		String renderedTitle = parsed.getGuide().getWikiTitle();
		wikiClient.fetchRenderedHtml(renderedTitle, htmlResponse -> wikiClient.executeAsync(() ->
		{
			WikiParsingResult enriched = isReady(htmlResponse)
				? wikiStrategyParser.mergeRenderedHtml(parsed, htmlResponse.getRevision().getText())
				: parsed;
			cache(title, enriched);
			clientThreadInvoker.accept(() ->
			{
				if (!isStale(staleCheck, requestId, staleTarget))
				{
					handleStrategyResult(requestId, staleTarget, candidates, parsedByTitle, index, staleCheck, handler, exhausted, enriched);
				}
			});
		}));
	}

	private void handleStrategyResult(
		int requestId,
		TargetOption staleTarget,
		List<String> candidates,
		Map<String, WikiParsingResult> parsedByTitle,
		int index,
		StaleCheck staleCheck,
		StrategyHandler handler,
		Runnable exhausted,
		WikiParsingResult result)
	{
		boolean finalCandidate = index == candidates.size() - 1;
		boolean handled = handler != null && handler.handle(result, finalCandidate);
		if (!handled)
		{
			continueStrategy(requestId, staleTarget, candidates, parsedByTitle, index + 1, staleCheck, handler, exhausted);
		}
	}

	private void continueVariantPage(
		int requestId,
		TargetOption target,
		List<String> candidates,
		Map<String, WikiParsingResult> parsedByTitle,
		int index,
		StaleCheck staleCheck,
		VariantHandler handler,
		Runnable exhausted)
	{
		if (isStale(staleCheck, requestId, target))
		{
			return;
		}
		if (index >= candidates.size())
		{
			exhausted.run();
			return;
		}

		String title = candidates.get(index);
		WikiParsingResult parsed = parsedByTitle.get(WikiTitles.cacheKey(title));
		if (parsed != null)
		{
			boolean handled = handler != null && handler.handle(parsed);
			if (handled)
			{
				return;
			}
		}
		continueVariantPage(requestId, target, candidates, parsedByTitle, index + 1, staleCheck, handler, exhausted);
	}

	private Map<String, WikiParsingResult> cachedResults(List<String> candidates)
	{
		Map<String, WikiParsingResult> result = new LinkedHashMap<>();
		synchronized (wikiResultCache)
		{
			for (String title : candidates)
			{
				String key = WikiTitles.cacheKey(title);
				WikiParsingResult cached = wikiResultCache.get(key);
				if (cached != null)
				{
					result.put(key, cached);
				}
			}
		}
		return result;
	}

	private WikiParsingResult cachedResult(String key)
	{
		synchronized (wikiResultCache)
		{
			return wikiResultCache.get(key);
		}
	}

	private void cache(String title, WikiParsingResult result)
	{
		if (result == null)
		{
			return;
		}
		synchronized (wikiResultCache)
		{
			wikiResultCache.put(WikiTitles.cacheKey(title), result);
		}
	}

	private WikiParsingResult parse(TargetOption target, WikiResponse response)
	{
		String name = target != null ? target.getDisplayName() : "";
		String title = response.getRevision().getTitle();
		return wikiStrategyParser.parse(
			name,
			title,
			WikiTitles.pageUrl(title),
			response.getRevision().getRevisionId(),
			response.getRevision().getText());
	}

	private boolean isReady(WikiResponse response)
	{
		return response != null && response.getState() == WikiState.READY && response.getRevision() != null;
	}

	private boolean isStale(StaleCheck staleCheck, int requestId, TargetOption target)
	{
		return staleCheck != null && staleCheck.isStale(requestId, target);
	}

	private List<String> safeCandidates(List<String> candidates)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> result = new ArrayList<>();
		Set<String> seen = new LinkedHashSet<>();
		for (String candidate : candidates)
		{
			if (candidate == null || candidate.trim().isEmpty())
			{
				continue;
			}
			String cleaned = candidate.trim();
			if (seen.add(WikiTitles.cacheKey(cleaned)))
			{
				result.add(cleaned);
			}
		}
		return Collections.unmodifiableList(result);
	}

	private Runnable safeRunnable(Runnable runnable)
	{
		return runnable != null ? runnable : () -> { };
	}

	public interface StaleCheck
	{
		boolean isStale(int requestId, TargetOption target);
	}

	public interface StrategyHandler
	{
		boolean handle(WikiParsingResult parsed, boolean finalCandidate);
	}

	public interface VariantHandler
	{
		boolean handle(WikiParsingResult parsed);
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.task.TargetOption;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public final class WikiPageCandidates
{
	private WikiPageCandidates()
	{
	}

	public static List<String> strategyPages(TargetOption target, String preferredStrategyPage)
	{
		Set<String> candidates = new LinkedHashSet<>();
		add(candidates, preferredStrategyPage);

		if (target == null)
		{
			return new ArrayList<>(candidates);
		}

		String wikiPage = target.getWikiPage();
		if (wikiPage != null && !wikiPage.trim().isEmpty())
		{
			String singular = WikiTitles.singularTitle(wikiPage);

			// Check standard strategy pages first
			add(candidates, target.getStrategyPage());
			add(candidates, "Strategies/" + wikiPage);
			add(candidates, wikiPage + "/Strategies");
			add(candidates, "Strategies/" + singular);
			add(candidates, singular + "/Strategies");

			// Fall back to Slayer_task pages if primary strategies return nothing
			add(candidates, "Slayer_task/" + wikiPage);
			add(candidates, "Slayer_task/" + singular);
		}

		return new ArrayList<>(candidates);
	}

	public static List<String> variantPages(TargetOption target)
	{
		Set<String> candidates = new LinkedHashSet<>();
		if (target != null)
		{
			String wikiPage = target.getWikiPage();
			addVariantPages(candidates, wikiPage);
			if (wikiPage != null && !wikiPage.trim().isEmpty())
			{
				addVariantPages(candidates, WikiTitles.singularTitle(wikiPage));
			}
		}
		return new ArrayList<>(candidates);
	}

	private static void addVariantPages(Set<String> candidates, String pageTitle)
	{
		if (pageTitle == null || pageTitle.trim().isEmpty())
		{
			return;
		}
		String cleaned = pageTitle.trim();
		candidates.add(cleaned);
		if (!cleaned.startsWith("Slayer_task/"))
		{
			candidates.add("Slayer_task/" + cleaned);
		}
	}

	private static void add(Set<String> candidates, String pageTitle)
	{
		if (pageTitle != null && !pageTitle.trim().isEmpty())
		{
			candidates.add(pageTitle.trim());
		}
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.task.TargetOption;
import java.util.Objects;

public class MonsterVariant
{
	private final String displayName;
	private final String wikiPageTitle;
	private final String wikiUrl;

	public MonsterVariant(String displayName, String wikiPageTitle, String wikiUrl)
	{
		this.displayName = displayName == null ? "" : displayName;
		this.wikiPageTitle = wikiPageTitle == null ? "" : wikiPageTitle;
		this.wikiUrl = wikiUrl == null ? "" : wikiUrl;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getWikiPageTitle()
	{
		return wikiPageTitle;
	}


	public TargetOption toTargetOption()
	{
		return new TargetOption(displayName, wikiPageTitle, "Strategies/" + wikiPageTitle);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		MonsterVariant that = (MonsterVariant) o;
		return displayName.equals(that.displayName) &&
				wikiPageTitle.equals(that.wikiPageTitle) &&
				wikiUrl.equals(that.wikiUrl);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(displayName, wikiPageTitle, wikiUrl);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.slayerprepassistant.wiki;

import com.slayerprepassistant.gear.GearRecommendation;
import com.slayerprepassistant.gear.GearSlot;
import com.slayerprepassistant.gear.GearTier;
import com.slayerprepassistant.gear.RecommendedItem;
import com.slayerprepassistant.guide.CombatMethod;
import com.slayerprepassistant.guide.InventoryRecommendation;
import com.slayerprepassistant.guide.MonsterGuide;
import com.slayerprepassistant.guide.StrategyMethod;
import com.slayerprepassistant.items.ItemResolver;
import com.slayerprepassistant.model.ParsingConfidence;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

class RenderedStrategyParser
{
	private static final int HTML_PATTERN_FLAGS = Pattern.DOTALL | Pattern.CASE_INSENSITIVE;
	private static final Pattern TABBER_TAB = Pattern.compile("<div[^>]*class=\"[^\"]*\\btabbertab\\b[^\"]*\"[^>]*data-title=\"([^\"]+)\"[^>]*>(.*?)(?=<div[^>]*class=\"[^\"]*\\btabbertab\\b|</div></div>\\s*<!--|$)", HTML_PATTERN_FLAGS);
	private static final Pattern TABBER_TITLE = Pattern.compile("<div[^>]*class=\"[^\"]*\\btabbertab\\b[^\"]*\"[^>]*data-title=\"([^\"]+)\"", HTML_PATTERN_FLAGS);
	private static final Pattern EQUIPMENT_TABLE = Pattern.compile("<table[^>]*class=\"(?=[^\"]*\\bequipment\\b)(?=[^\"]*\\bequipment-right\\b)[^\"]*\"[^>]*>(.*?)</table>", HTML_PATTERN_FLAGS);
	private static final Pattern INVENTORY_TABLE = Pattern.compile("<table[^>]*class=\"(?=[^\"]*\\binventorytable\\b)(?=[^\"]*\\bstorage-right\\b)[^\"]*\"[^>]*>(.*?)</table>", HTML_PATTERN_FLAGS);
	private static final Pattern EQUIPMENT_DIV = Pattern.compile("<div[^>]*class=\"[^\"]*\\bequipment-div\\b[^\"]*\"[^>]*>(.*?)(?=<table|<div[^>]*class=\"[^\"]*\\btabbertab\\b|$)", HTML_PATTERN_FLAGS);
	private static final Pattern EQUIPMENT_SLOT_START = Pattern.compile("<div class=\"equipment-(head|cape|neck|ammo2?|weapon|body|torso|shield|legs|hands|gloves|feet|boots|ring)(?:\\s|\"|-)[^\"]*\">", Pattern.DOTALL);
	private static final Pattern HTML_LINK = Pattern.compile("<a\\s+([^>]*)>", Pattern.DOTALL);
	private static final Pattern HTML_HREF = Pattern.compile("href=\"/w/([^\"]+)\"");
	private static final Pattern HTML_TITLE = Pattern.compile("title=\"([^\"]+)\"");
	private static final Pattern HTML_IMAGE = Pattern.compile("(?:<img\\s+([^>]*)>|!\\[[^\\]]*]\\((/images/[^)]+)\\))", Pattern.DOTALL);
	private static final Pattern HTML_SRC = Pattern.compile("(?:src|data-src)=\"([^\"]+)\"");
	private static final Pattern HTML_ALT = Pattern.compile("alt=\"([^\"]+)\"");

	WikiParsingResult mergeInto(WikiParsingResult source, String renderedHtml)
	{
		if (source == null || renderedHtml == null || renderedHtml.isEmpty())
		{
			return source;
		}

		CombatMethod fallbackMethod = fallbackMethod(source);
		List<StrategyMethod> htmlMethods = parseMethods(renderedHtml, fallbackMethod);
		if (htmlMethods.isEmpty())
		{
			return source;
		}

		List<StrategyMethod> mergedMethods = new ArrayList<>();
		for (StrategyMethod sourceMethod : source.getGuide().getMethods())
		{
			StrategyMethod htmlMethod = findMethod(htmlMethods, sourceMethod.getMethod());
			if (htmlMethod == null)
			{
				mergedMethods.add(sourceMethod);
			}
			else
			{
				mergedMethods.add(new StrategyMethod(
						sourceMethod.getMethod(),
						mergeGearPreferRendered(htmlMethod.getGear(), sourceMethod.getGear()),
						mergeInventory(htmlMethod.getInventory(), sourceMethod.getInventory()),
						sourceMethod.getNotes(),
						sourceMethod.getConfidence()));
			}
		}

		htmlMethods.stream()
				.filter(hm -> findMethod(mergedMethods, hm.getMethod()) == null)
				.forEach(mergedMethods::add);

		MonsterGuide guide = source.getGuide();
		return new WikiParsingResult(
				new MonsterGuide(guide.getMonsterName(), guide.getWikiTitle(), guide.getWikiUrl(), guide.getRevisionId(), guide.getFetchedAt(), mergedMethods, guide.getNotes(), guide.getConfidence()),
				source.getVariants(),
				source.getWarnings());
	}

	private CombatMethod fallbackMethod(WikiParsingResult source)
	{
		List<StrategyMethod> methods = source.getGuide().getMethods();
		return methods.size() == 1 ? methods.get(0).getMethod() : null;
	}

	private List<StrategyMethod> parseMethods(String html, CombatMethod fallbackMethod)
	{
		List<StrategyMethod> methods = new ArrayList<>();
		Matcher tabMatcher = TABBER_TAB.matcher(html);
		boolean sawTab = false;
		boolean hasCombatLabeledTab = hasCombatLabeledTab(html);

		while (tabMatcher.find())
		{
			sawTab = true;
			String title = htmlText(tabMatcher.group(1));
			CombatMethod method = methodForHeading(title.toLowerCase(Locale.ROOT));
			String tabHtml = tabMatcher.group(2);

			// A generic outer/location tab (for example "Catacombs") must not inherit
			// the source method when the page also contains explicitly-labelled combat tabs.
			// Doing so is what previously allowed Magic/Ranged gear to be merged into Melee.
			if (method == null && !hasCombatLabeledTab && fallbackMethod != null && equipmentBlockCount(tabHtml) <= 1)
			{
				method = fallbackMethod;
			}
			if (method == null)
			{
				continue;
			}

			List<GearRecommendation> gear = parseEquipment(tabHtml);
			List<InventoryRecommendation> inventory = parseInventory(tabHtml);

			if ((!gear.isEmpty() || !inventory.isEmpty()) && findMethod(methods, method) == null)
			{
				methods.add(new StrategyMethod(method, gear, inventory, Collections.emptyList(), ParsingConfidence.HIGH));
			}
		}
		if (!sawTab && fallbackMethod != null && equipmentBlockCount(html) <= 1)
		{
			List<GearRecommendation> gear = parseEquipment(html);
			List<InventoryRecommendation> inventory = parseInventory(html);
			if (!gear.isEmpty() || !inventory.isEmpty())
			{
				methods.add(new StrategyMethod(fallbackMethod, gear, inventory, Collections.emptyList(), ParsingConfidence.HIGH));
			}
		}
		return methods;
	}

	private boolean hasCombatLabeledTab(String html)
	{
		Matcher matcher = TABBER_TITLE.matcher(html);
		while (matcher.find())
		{
			if (methodForHeading(htmlText(matcher.group(1)).toLowerCase(Locale.ROOT)) != null)
			{
				return true;
			}
		}
		return false;
	}

	private int equipmentBlockCount(String html)
	{
		if (html == null || html.isEmpty())
		{
			return 0;
		}
		int count = 0;
		Matcher tableMatcher = EQUIPMENT_TABLE.matcher(html);
		while (tableMatcher.find())
		{
			count++;
		}
		if (count > 0)
		{
			return count;
		}
		Matcher divMatcher = EQUIPMENT_DIV.matcher(html);
		while (divMatcher.find())
		{
			count++;
		}
		return count;
	}

	private CombatMethod methodForHeading(String heading)
	{
		if (heading.contains("melee")) return CombatMethod.MELEE;
		if (heading.contains("ranged") || heading.contains("range")) return CombatMethod.RANGED;
		if (heading.contains("magic") || heading.contains("mage")) return CombatMethod.MAGIC;
		return null;
	}

	private StrategyMethod findMethod(List<StrategyMethod> methods, CombatMethod method)
	{
		return methods.stream()
				.filter(m -> m.getMethod() == method)
				.findFirst()
				.orElse(null);
	}

	private List<GearRecommendation> mergeGearPreferRendered(List<GearRecommendation> rendered, List<GearRecommendation> source)
	{
		Map<GearSlot, GearRecommendation> bySlot = new EnumMap<>(GearSlot.class);
		if (source != null)
		{
			for (GearRecommendation recommendation : source)
			{
				if (recommendation != null && recommendation.getSlot() != null)
				{
					bySlot.put(recommendation.getSlot(), recommendation);
				}
			}
		}
		if (rendered != null)
		{
			for (GearRecommendation recommendation : rendered)
			{
				if (recommendation != null && recommendation.getSlot() != null && recommendation.getTiers() != null && !recommendation.getTiers().isEmpty())
				{
					GearRecommendation sourceRecommendation = bySlot.get(recommendation.getSlot());
					if (sourceRecommendation == null
							|| !hasRankedAlternatives(sourceRecommendation)
							|| isRicherRecommendation(recommendation, sourceRecommendation))
					{
						bySlot.put(recommendation.getSlot(), recommendation);
					}
				}
			}
		}
		return new ArrayList<>(bySlot.values());
	}

	private boolean hasRankedAlternatives(GearRecommendation recommendation)
	{
		return tierCount(recommendation) > 1 || itemCount(recommendation) > 1;
	}

	private boolean isRicherRecommendation(GearRecommendation candidate, GearRecommendation existing)
	{
		return itemCount(candidate) > itemCount(existing) || tierCount(candidate) > tierCount(existing);
	}

	private int tierCount(GearRecommendation recommendation)
	{
		return recommendation == null || recommendation.getTiers() == null ? 0 : recommendation.getTiers().size();
	}

	private int itemCount(GearRecommendation recommendation)
	{
		if (recommendation == null || recommendation.getTiers() == null)
		{
			return 0;
		}
		int count = 0;
		for (GearTier tier : recommendation.getTiers())
		{
			if (tier != null && tier.getAlternatives() != null)
			{
				count += tier.getAlternatives().size();
			}
		}
		return count;
	}

	private List<InventoryRecommendation> mergeInventory(List<InventoryRecommendation> rendered, List<InventoryRecommendation> source)
	{
		if ((rendered == null || rendered.isEmpty()) && (source == null || source.isEmpty()))
		{
			return Collections.emptyList();
		}

		Map<String, InventoryRecommendation> merged = new LinkedHashMap<>();
		if (rendered != null)
		{
			for (InventoryRecommendation recommendation : rendered)
			{
				mergeInventoryRecommendation(merged, recommendation);
			}
		}
		if (source != null)
		{
			for (InventoryRecommendation recommendation : source)
			{
				mergeInventoryRecommendation(merged, recommendation);
			}
		}
		return new ArrayList<>(merged.values());
	}

	private void mergeInventoryRecommendation(Map<String, InventoryRecommendation> merged, InventoryRecommendation recommendation)
	{
		if (recommendation == null)
		{
			return;
		}
		String key = ItemResolver.canonicalKey(recommendation.getItemOrCategory());
		if (key.isEmpty())
		{
			return;
		}
		InventoryRecommendation existing = merged.get(key);
		if (existing == null)
		{
			merged.put(key, recommendation);
			return;
		}
		merged.put(key, new InventoryRecommendation(
			existing.getItemOrCategory(),
			Math.max(existing.getMinimumQuantity(), recommendation.getMinimumQuantity()),
			existing.isRequired() || recommendation.isRequired()));
	}

	private List<GearRecommendation> parseEquipment(String html)
	{
		List<String> blocks = equipmentBlocks(html);
		if (blocks.isEmpty())
		{
			return Collections.emptyList();
		}

		Map<GearSlot, List<GearTier>> bySlot = new EnumMap<>(GearSlot.class);
		for (String tableHtml : blocks)
		{
			Matcher slotMatcher = EQUIPMENT_SLOT_START.matcher(tableHtml);
			while (slotMatcher.find())
			{
				GearSlot slot = WikiGearSlots.parse(slotMatcher.group(1));
				int slotStart = slotMatcher.end();
				int slotEnd = nextSlotStart(tableHtml, slotStart);
				List<RecommendedItem> items = htmlItems(tableHtml.substring(slotStart, slotEnd));

				if (slot != null && !items.isEmpty())
				{
					bySlot.put(slot, Collections.singletonList(new GearTier(0, items)));
				}
			}
		}

		return bySlot.entrySet().stream()
				.map(entry -> new GearRecommendation(entry.getKey(), entry.getValue()))
				.collect(Collectors.toList());
	}

	private List<String> equipmentBlocks(String html)
	{
		List<String> blocks = new ArrayList<>();
		Matcher tableMatcher = EQUIPMENT_TABLE.matcher(html);
		while (tableMatcher.find())
		{
			blocks.add(tableMatcher.group(1));
		}
		if (!blocks.isEmpty())
		{
			return blocks;
		}
		Matcher divMatcher = EQUIPMENT_DIV.matcher(html);
		while (divMatcher.find())
		{
			blocks.add(divMatcher.group(1));
		}
		return blocks;
	}

	private int nextSlotStart(String html, int start)
	{
		Matcher matcher = EQUIPMENT_SLOT_START.matcher(html);
		return matcher.find(start) ? matcher.start() : html.length();
	}

	private List<InventoryRecommendation> parseInventory(String html)
	{
		Matcher tableMatcher = INVENTORY_TABLE.matcher(html);
		Map<String, InventoryRecommendation> inventory = new LinkedHashMap<>();
		while (tableMatcher.find())
		{
			for (RecommendedItem item : htmlItems(tableMatcher.group(1)))
			{
				mergeInventoryRecommendation(inventory, new InventoryRecommendation(item.getName(), 0, true));
			}
		}
		return inventory.isEmpty() ? Collections.emptyList() : new ArrayList<>(inventory.values());
	}

	private List<RecommendedItem> htmlItems(String html)
	{
		List<RecommendedItem> items = new ArrayList<>();

		Matcher linkMatcher = HTML_LINK.matcher(html);
		while (linkMatcher.find())
		{
			String attributes = linkMatcher.group(1);
			Matcher hrefMatcher = HTML_HREF.matcher(attributes);
			Matcher titleMatcher = HTML_TITLE.matcher(attributes);

			if (hrefMatcher.find() && titleMatcher.find() && !hrefMatcher.group(1).contains(":"))
			{
				String name = htmlText(titleMatcher.group(1));
				if (isUsableItemTitle(name) && !containsRecommended(items, name))
				{
					items.add(new RecommendedItem(name));
				}
			}
		}

		Matcher imageMatcher = HTML_IMAGE.matcher(html);
		while (imageMatcher.find())
		{
			String attributes = imageMatcher.group(1);
			String markdownSrc = imageMatcher.group(2);
			String name = itemNameFromImage(attributes, markdownSrc);
			if (isUsableItemTitle(name) && !containsRecommended(items, name))
			{
				items.add(new RecommendedItem(name));
			}
		}
		return items;
	}

	private String itemNameFromImage(String attributes, String markdownSrc)
	{
		if (attributes != null)
		{
			Matcher altMatcher = HTML_ALT.matcher(attributes);
			if (altMatcher.find())
			{
				String alt = htmlText(altMatcher.group(1));
				if (isUsableItemTitle(alt))
				{
					return alt.replaceFirst("\\.png$", "");
				}
			}
			Matcher srcMatcher = HTML_SRC.matcher(attributes);
			if (srcMatcher.find())
			{
				return itemNameFromImagePath(srcMatcher.group(1));
			}
		}
		return itemNameFromImagePath(markdownSrc);
	}

	private String itemNameFromImagePath(String src)
	{
		if (src == null || src.trim().isEmpty())
		{
			return "";
		}
		String path = src;
		int query = path.indexOf('?');
		if (query >= 0)
		{
			path = path.substring(0, query);
		}
		int slash = path.lastIndexOf('/');
		String fileName = slash >= 0 ? path.substring(slash + 1) : path;
		if (fileName.toLowerCase(Locale.ROOT).endsWith(".png"))
		{
			fileName = fileName.substring(0, fileName.length() - ".png".length());
		}
		if (fileName.matches(".*%29_\\d+$"))
		{
			fileName = fileName.replaceFirst("_\\d+$", "");
		}
		try
		{
			String decoded = URLDecoder.decode(fileName.replace('_', ' '), StandardCharsets.UTF_8);
			return htmlText(decoded);
		}
		catch (IllegalArgumentException ex)
		{
			return htmlText(fileName.replace('_', ' '));
		}
	}

	private boolean isUsableItemTitle(String name)
	{
		String normalized = name.toLowerCase(Locale.ROOT).trim();
		return !normalized.isEmpty()
				&& !normalized.endsWith(" slot")
				&& !normalized.contains("placeholder")
				&& !normalized.equals("special attack")
				&& !normalized.equals("empty")
				&& !normalized.equals("n/a")
				&& !normalized.equals("none");
	}

	private boolean containsRecommended(List<RecommendedItem> items, String name)
	{
		return items.stream().anyMatch(item -> item.getName().equalsIgnoreCase(name));
	}

	private String htmlText(String value)
	{
		return value == null ? "" : value
				.replace("&amp;", "&")
				.replace("&#39;", "'")
				.replace("&#039;", "'")
				.replace("&apos;", "'")
				.replace("&quot;", "\"")
				.replace("&nbsp;", " ")
				.replaceAll("\\s+", " ")
				.trim();
	}
}

package com.slayerprepassistant.wiki;

import com.google.gson.Gson;
import com.slayerprepassistant.PluginUrls;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

public class WikiClient
{
	public static final String USER_AGENT = "SlayerPrepAssistant-RuneLite/0.0.1";
	private static final int MAX_TITLES_PER_QUERY = 50;
	private static final int REVISION_CACHE_SIZE = 128;
	private static final int RENDERED_CACHE_SIZE = 64;
	private static final int IMAGE_CACHE_SIZE = 128;
	private static final int IMAGE_MISS_CACHE_SIZE = 256;
	private static final int IMAGE_METADATA_BATCH_DELAY_MS = 12;

	private final OkHttpClient httpClient;
	private final WikiApiResponseParser responseParser;
	private final Map<String, WikiResponse> revisionCache = lruMap(REVISION_CACHE_SIZE);
	private final Map<String, WikiResponse> renderedCache = lruMap(RENDERED_CACHE_SIZE);
	private final Map<String, BufferedImage> imageCache = lruMap(IMAGE_CACHE_SIZE);
	private final Map<String, Boolean> imageMissCache = lruMap(IMAGE_MISS_CACHE_SIZE);
	private final Map<String, List<Consumer<WikiResponse>>> pendingRevisions = new LinkedHashMap<>();
	private final Map<String, List<Consumer<WikiResponse>>> pendingRendered = new LinkedHashMap<>();
	private final Map<String, List<Consumer<BufferedImage>>> pendingImages = new LinkedHashMap<>();
	private final Map<Integer, LinkedHashMap<String, String>> queuedImageTitlesBySize = new LinkedHashMap<>();
	private final ScheduledExecutorService imageBatchExecutor = Executors.newSingleThreadScheduledExecutor(runnable ->
	{
		Thread thread = new Thread(runnable, "slayer-prep-wiki-image-batch");
		thread.setDaemon(true);
		return thread;
	});
	private ScheduledFuture<?> imageBatchTask;
	private final Set<Call> activeCalls = Collections.newSetFromMap(new ConcurrentHashMap<Call, Boolean>());
	private volatile boolean closed;

	public WikiClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.responseParser = new WikiApiResponseParser(gson);
	}

	public void fetchRevisionText(String title, Consumer<WikiResponse> callback)
	{
		fetchRevisionTexts(Collections.singletonList(title), responses ->
		{
			if (callback != null)
			{
				callback.accept(responses.getOrDefault(
					WikiTitles.cacheKey(title),
					new WikiResponse(WikiState.ERROR, null, "Wiki page not found")));
			}
		});
	}

	public void fetchRevisionTexts(List<String> titles, Consumer<Map<String, WikiResponse>> callback)
	{
		if (callback == null)
		{
			return;
		}
		Map<String, String> requestedTitles = distinctTitles(titles);
		if (requestedTitles.isEmpty())
		{
			callback.accept(Collections.emptyMap());
			return;
		}
		if (closed)
		{
			callback.accept(errorResponses(requestedTitles, "Wiki client is closed"));
			return;
		}

		Map<String, WikiResponse> collected = new ConcurrentHashMap<>();
		AtomicInteger remaining = new AtomicInteger(requestedTitles.size());
		Consumer<KeyedWikiResponse> collector = keyed ->
		{
			collected.put(keyed.key, keyed.response);
			if (remaining.decrementAndGet() == 0)
			{
				Map<String, WikiResponse> ordered = new LinkedHashMap<>();
				for (String key : requestedTitles.keySet())
				{
					ordered.put(key, collected.getOrDefault(key, new WikiResponse(WikiState.ERROR, null, "Wiki page not found")));
				}
				callback.accept(Collections.unmodifiableMap(ordered));
			}
		};

		List<String> freshTitles = new ArrayList<>();
		List<KeyedWikiResponse> cachedResponses = new ArrayList<>();
		synchronized (this)
		{
			for (Map.Entry<String, String> entry : requestedTitles.entrySet())
			{
				String key = entry.getKey();
				WikiResponse cached = revisionCache.get(key);
				if (cached != null)
				{
					cachedResponses.add(new KeyedWikiResponse(key, cached));
					continue;
				}

				Consumer<WikiResponse> perTitleCallback = response -> collector.accept(new KeyedWikiResponse(key, response));
				List<Consumer<WikiResponse>> pending = pendingRevisions.get(key);
				if (pending != null)
				{
					pending.add(perTitleCallback);
				}
				else
				{
					pendingRevisions.put(key, new ArrayList<>(Collections.singletonList(perTitleCallback)));
					freshTitles.add(entry.getValue());
				}
			}
		}

		for (KeyedWikiResponse cached : cachedResponses)
		{
			collector.accept(cached);
		}
		for (int start = 0; start < freshTitles.size(); start += MAX_TITLES_PER_QUERY)
		{
			int end = Math.min(freshTitles.size(), start + MAX_TITLES_PER_QUERY);
			enqueueRevisionBatch(new ArrayList<>(freshTitles.subList(start, end)));
		}
	}

	public void fetchRenderedHtml(String title, Consumer<WikiResponse> callback)
	{
		if (callback == null)
		{
			return;
		}
		if (closed)
		{
			callback.accept(new WikiResponse(WikiState.ERROR, null, "Wiki client is closed"));
			return;
		}
		String key = WikiTitles.cacheKey(title);
		WikiResponse cached;
		synchronized (this)
		{
			cached = renderedCache.get(key);
			if (cached == null && pendingRendered.containsKey(key))
			{
				pendingRendered.get(key).add(callback);
				return;
			}
			if (cached == null)
			{
				pendingRendered.put(key, new ArrayList<>(Collections.singletonList(callback)));
			}
		}
		if (cached != null)
		{
			callback.accept(cached);
			return;
		}

		HttpUrl url = apiUrlBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", "text|revid")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.build();
		Call call = httpClient.newCall(request(url));
		if (!track(call))
		{
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				untrack(call);
				completeWikiResponse(pendingRendered, renderedCache, key, error(e));
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				untrack(call);
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						completeWikiResponse(pendingRendered, renderedCache, key, httpError(response.code()));
						return;
					}
					completeWikiResponse(pendingRendered, renderedCache, key, responseParser.parseRendered(title, body.string()));
				}
			}
		});
	}

	public void fetchPageImage(String title, int size, Consumer<BufferedImage> callback)
	{
		if (callback == null)
		{
			return;
		}
		if (closed || title == null || title.trim().isEmpty() || size <= 0)
		{
			callback.accept(null);
			return;
		}

		String cleanedTitle = title.trim();
		String titleKey = WikiTitles.cacheKey(cleanedTitle);
		String key = titleKey + "|" + size;
		BufferedImage cached;
		boolean cachedMiss;
		boolean newRequest = false;
		synchronized (this)
		{
			cached = imageCache.get(key);
			cachedMiss = imageMissCache.containsKey(key);
			if (cached == null && !cachedMiss)
			{
				List<Consumer<BufferedImage>> pending = pendingImages.get(key);
				if (pending != null)
				{
					pending.add(callback);
					return;
				}
				pendingImages.put(key, new ArrayList<>(Collections.singletonList(callback)));
				queuedImageTitlesBySize.computeIfAbsent(size, ignored -> new LinkedHashMap<>()).put(titleKey, cleanedTitle);
				newRequest = true;
			}
		}
		if (cached != null || cachedMiss)
		{
			callback.accept(cached);
			return;
		}
		if (newRequest)
		{
			scheduleImageMetadataFlush();
		}
	}

	void executeAsync(Runnable task)
	{
		if (task == null || closed)
		{
			return;
		}
		httpClient.dispatcher().executorService().execute(task);
	}

	public void cancelOutstanding()
	{
		closed = true;
		synchronized (this)
		{
			if (imageBatchTask != null)
			{
				imageBatchTask.cancel(false);
				imageBatchTask = null;
			}
			queuedImageTitlesBySize.clear();
			pendingRevisions.clear();
			pendingRendered.clear();
			pendingImages.clear();
			revisionCache.clear();
			renderedCache.clear();
			imageCache.clear();
			imageMissCache.clear();
		}
		imageBatchExecutor.shutdownNow();
		for (Call call : new ArrayList<>(activeCalls))
		{
			call.cancel();
		}
		activeCalls.clear();
	}

	private void scheduleImageMetadataFlush()
	{
		synchronized (this)
		{
			if (closed || (imageBatchTask != null && !imageBatchTask.isDone()))
			{
				return;
			}
			try
			{
				imageBatchTask = imageBatchExecutor.schedule(this::flushImageMetadata, IMAGE_METADATA_BATCH_DELAY_MS, TimeUnit.MILLISECONDS);
			}
			catch (RejectedExecutionException ignored)
			{
				imageBatchTask = null;
			}
		}
	}

	private void flushImageMetadata()
	{
		Map<Integer, LinkedHashMap<String, String>> queued;
		synchronized (this)
		{
			imageBatchTask = null;
			if (closed || queuedImageTitlesBySize.isEmpty())
			{
				return;
			}
			queued = new LinkedHashMap<>();
			for (Map.Entry<Integer, LinkedHashMap<String, String>> entry : queuedImageTitlesBySize.entrySet())
			{
				queued.put(entry.getKey(), new LinkedHashMap<>(entry.getValue()));
			}
			queuedImageTitlesBySize.clear();
		}

		for (Map.Entry<Integer, LinkedHashMap<String, String>> entry : queued.entrySet())
		{
			List<Map.Entry<String, String>> requests = new ArrayList<>(entry.getValue().entrySet());
			for (int start = 0; start < requests.size(); start += MAX_TITLES_PER_QUERY)
			{
				int end = Math.min(requests.size(), start + MAX_TITLES_PER_QUERY);
				enqueueImageMetadataBatch(entry.getKey(), new ArrayList<>(requests.subList(start, end)));
			}
		}
	}

	private void enqueueImageMetadataBatch(int size, List<Map.Entry<String, String>> requests)
	{
		if (closed || requests == null || requests.isEmpty())
		{
			return;
		}
		List<String> titles = new ArrayList<>(requests.size());
		for (Map.Entry<String, String> request : requests)
		{
			titles.add(request.getValue());
		}

		HttpUrl url = apiUrlBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "pageimages")
			.addQueryParameter("piprop", "thumbnail")
			.addQueryParameter("pithumbsize", String.valueOf(size))
			.addQueryParameter("titles", String.join("|", titles))
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.build();
		Call call = httpClient.newCall(request(url));
		if (!track(call))
		{
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				untrack(call);
				for (Map.Entry<String, String> request : requests)
				{
					completeImageResponse(request.getKey() + "|" + size, null, false);
				}
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				untrack(call);
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						for (Map.Entry<String, String> request : requests)
						{
							completeImageResponse(request.getKey() + "|" + size, null, false);
						}
						return;
					}

					Map<String, String> imageSources = responseParser.pageImageSources(titles, body.string());
					for (Map.Entry<String, String> request : requests)
					{
						String key = request.getKey() + "|" + size;
						String imageSource = imageSources.getOrDefault(request.getKey(), "");
						if (imageSource.isEmpty())
						{
							completeImageResponse(key, null, true);
						}
						else
						{
							fetchImage(key, imageSource);
						}
					}
				}
			}
		});
	}

	private void enqueueRevisionBatch(List<String> titles)
	{
		if (titles == null || titles.isEmpty())
		{
			return;
		}
		HttpUrl url = apiUrlBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("rvprop", "ids|content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("titles", String.join("|", titles))
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.build();
		Call call = httpClient.newCall(request(url));
		if (!track(call))
		{
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				untrack(call);
				WikiResponse failure = error(e);
				for (String title : titles)
				{
					completeWikiResponse(pendingRevisions, revisionCache, WikiTitles.cacheKey(title), failure);
				}
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				untrack(call);
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						WikiResponse failure = httpError(response.code());
						for (String title : titles)
						{
							completeWikiResponse(pendingRevisions, revisionCache, WikiTitles.cacheKey(title), failure);
						}
						return;
					}
					Map<String, WikiResponse> parsed = responseParser.parseRevisions(titles, body.string());
					for (String title : titles)
					{
						String key = WikiTitles.cacheKey(title);
						completeWikiResponse(pendingRevisions, revisionCache, key,
							parsed.getOrDefault(key, new WikiResponse(WikiState.ERROR, null, "Wiki page not found")));
					}
				}
			}
		});
	}

	private void fetchImage(String key, String imageSource)
	{
		if (closed)
		{
			completeImageResponse(key, null, false);
			return;
		}
		HttpUrl imageUrl = PluginUrls.osrsWikiImageUrlFromMediaWikiSource(imageSource);
		if (imageUrl == null)
		{
			completeImageResponse(key, null, true);
			return;
		}

		Call call = httpClient.newCall(request(imageUrl));
		if (!track(call))
		{
			return;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				untrack(call);
				completeImageResponse(key, null, false);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				untrack(call);
				try (ResponseBody body = response.body())
				{
					BufferedImage image = response.isSuccessful() && body != null ? ImageIO.read(body.byteStream()) : null;
					completeImageResponse(key, image, response.isSuccessful());
				}
			}
		});
	}

	private void completeWikiResponse(
		Map<String, List<Consumer<WikiResponse>>> pending,
		Map<String, WikiResponse> cache,
		String key,
		WikiResponse response)
	{
		List<Consumer<WikiResponse>> callbacks;
		synchronized (this)
		{
			if (!closed && isCacheable(response))
			{
				cache.put(key, response);
			}
			callbacks = pending.remove(key);
		}
		if (callbacks != null)
		{
			for (Consumer<WikiResponse> callback : callbacks)
			{
				callback.accept(response);
			}
		}
	}

	private boolean isCacheable(WikiResponse response)
	{
		return response != null
			&& (response.getState() == WikiState.READY
				|| (response.getMessage() != null && response.getMessage().toLowerCase(java.util.Locale.ROOT).contains("not found")));
	}

	private void completeImageResponse(String key, BufferedImage image, boolean cacheMiss)
	{
		List<Consumer<BufferedImage>> callbacks;
		synchronized (this)
		{
			if (!closed)
			{
				if (image != null)
				{
					imageCache.put(key, image);
				}
				else if (cacheMiss)
				{
					imageMissCache.put(key, true);
				}
			}
			callbacks = pendingImages.remove(key);
		}
		if (callbacks != null)
		{
			for (Consumer<BufferedImage> callback : callbacks)
			{
				callback.accept(image);
			}
		}
	}

	private Request request(HttpUrl url)
	{
		return new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
	}

	private HttpUrl.Builder apiUrlBuilder()
	{
		return PluginUrls.osrsWikiApiEndpointBuilder();
	}

	private boolean track(Call call)
	{
		if (call == null || closed)
		{
			if (call != null)
			{
				call.cancel();
			}
			return false;
		}
		activeCalls.add(call);
		if (closed && activeCalls.remove(call))
		{
			call.cancel();
			return false;
		}
		return true;
	}

	private void untrack(Call call)
	{
		activeCalls.remove(call);
	}

	private WikiResponse error(IOException e)
	{
		return new WikiResponse(WikiState.ERROR, null, e == null || e.getMessage() == null ? "Wiki request failed" : e.getMessage());
	}

	private WikiResponse httpError(int code)
	{
		return new WikiResponse(WikiState.ERROR, null, "Wiki returned HTTP " + code);
	}

	private Map<String, String> distinctTitles(List<String> titles)
	{
		Map<String, String> result = new LinkedHashMap<>();
		if (titles == null)
		{
			return result;
		}
		for (String title : titles)
		{
			if (title == null || title.trim().isEmpty())
			{
				continue;
			}
			String cleaned = title.trim();
			result.putIfAbsent(WikiTitles.cacheKey(cleaned), cleaned);
		}
		return result;
	}

	private Map<String, WikiResponse> errorResponses(Map<String, String> requestedTitles, String message)
	{
		Map<String, WikiResponse> result = new LinkedHashMap<>();
		for (String key : requestedTitles.keySet())
		{
			result.put(key, new WikiResponse(WikiState.ERROR, null, message));
		}
		return result;
	}

	private static <K, V> Map<K, V> lruMap(int maximumSize)
	{
		return new LinkedHashMap<K, V>(16, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<K, V> eldest)
			{
				return size() > maximumSize;
			}
		};
	}

	private static final class KeyedWikiResponse
	{
		private final String key;
		private final WikiResponse response;

		private KeyedWikiResponse(String key, WikiResponse response)
		{
			this.key = key;
			this.response = response == null ? new WikiResponse(WikiState.ERROR, null, "Wiki request failed") : response;
		}
	}
}

