package com.slayerprepassistant.bank;

import com.slayerprepassistant.items.ItemResolver;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;

public class BankSnapshotService
{
	private volatile BankSnapshot snapshot = BankSnapshot.emptyUnknown();

	public void updateFromBankContainer(ItemContainer container, Client client)
	{
		if (container == null)
		{
			return;
		}
		ContainerSnapshot captured = capture(container, client, true);
		BankSnapshot next = new BankSnapshot(captured.quantitiesById, captured.itemNames, captured.quantitiesByCanonicalName, Instant.now());
		if (!next.equals(snapshot))
		{
			snapshot = next;
		}
	}

	public BankSnapshot getSnapshot()
	{
		return snapshot;
	}

	public static Map<Integer, Integer> toQuantities(ItemContainer container)
	{
		return toQuantities(container, Collections.emptySet());
	}

	static Map<Integer, Integer> toQuantities(ItemContainer container, Set<Integer> ignoredIds)
	{
		if (container == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (isUsable(item) && (ignoredIds == null || !ignoredIds.contains(item.getId())))
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return quantities;
	}

	public static Set<String> toNames(ItemContainer container, Client client)
	{
		return capture(container, client, false).itemNames;
	}

	static ContainerSnapshot capture(ItemContainer container, Client client, boolean ignorePlaceholders)
	{
		if (container == null)
		{
			return ContainerSnapshot.empty();
		}

		Map<Integer, Integer> quantities = new HashMap<>();
		Set<String> names = new HashSet<>();
		Map<String, Integer> quantitiesByCanonicalName = new HashMap<>();
		Map<Integer, ItemComposition> compositionsById = new HashMap<>();

		for (Item item : container.getItems())
		{
			if (!isUsable(item))
			{
				continue;
			}

			ItemComposition composition = null;
			if (client != null)
			{
				composition = compositionsById.computeIfAbsent(item.getId(), client::getItemDefinition);
				if (ignorePlaceholders && composition != null && composition.getPlaceholderTemplateId() >= 0)
				{
					continue;
				}
			}

			quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			if (composition == null || composition.getName() == null || composition.getName().trim().isEmpty())
			{
				continue;
			}

			String name = composition.getName();
			names.add(name);
			String canonical = ItemResolver.canonicalKey(name);
			if (!canonical.isEmpty())
			{
				quantitiesByCanonicalName.merge(canonical, item.getQuantity(), Integer::sum);
			}
		}

		return new ContainerSnapshot(quantities, names, quantitiesByCanonicalName);
	}

	private static boolean isUsable(Item item)
	{
		return item != null && item.getId() > 0 && item.getQuantity() > 0;
	}

	static final class ContainerSnapshot
	{
		final Map<Integer, Integer> quantitiesById;
		final Set<String> itemNames;
		final Map<String, Integer> quantitiesByCanonicalName;

		private ContainerSnapshot(Map<Integer, Integer> quantitiesById, Set<String> itemNames, Map<String, Integer> quantitiesByCanonicalName)
		{
			this.quantitiesById = quantitiesById;
			this.itemNames = itemNames;
			this.quantitiesByCanonicalName = quantitiesByCanonicalName;
		}

		private static ContainerSnapshot empty()
		{
			return new ContainerSnapshot(Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap());
		}
	}
}

package com.slayerprepassistant.bank;

import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

public class PlayerStateTracker
{
	private final BankSnapshotService bankSnapshotService = new BankSnapshotService();
	private PlayerInventoryState state = PlayerInventoryState.unknownBank();
	private long stateRevision;

	public void updateBank(ItemContainer container, Client client)
	{
		bankSnapshotService.updateFromBankContainer(container, client);
	}

	public boolean update(Client client)
	{
		if (client == null)
		{
			return false;
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		BankSnapshotService.ContainerSnapshot equipmentSnapshot = BankSnapshotService.capture(equipment, client, false);
		BankSnapshotService.ContainerSnapshot inventorySnapshot = BankSnapshotService.capture(inventory, client, false);
		PlayerInventoryState nextState = new PlayerInventoryState(
			equipmentSnapshot.quantitiesById,
			inventorySnapshot.quantitiesById,
			equipmentSnapshot.itemNames,
			inventorySnapshot.itemNames,
			equipmentSnapshot.quantitiesByCanonicalName,
			inventorySnapshot.quantitiesByCanonicalName,
			bankSnapshotService.getSnapshot());

		if (nextState.equals(state))
		{
			return false;
		}
		state = nextState;
		stateRevision++;
		return true;
	}

	public PlayerInventoryState getState()
	{
		return state;
	}

	public String getStateKey()
	{
		return Long.toString(stateRevision);
	}
}

package com.slayerprepassistant.task;

import java.util.Objects;

public class SlayerTaskContext
{
	private static final SlayerTaskContext NONE = new SlayerTaskContext("", 0, 0, "", false);

	private final String taskName;
	private final int remainingAmount;
	private final int initialAmount;
	private final String assignedLocation;
	private final boolean active;

	public SlayerTaskContext(String taskName, int remainingAmount, int initialAmount, String assignedLocation, boolean active)
	{
		this.taskName = taskName == null ? "" : taskName;
		this.remainingAmount = Math.max(0, remainingAmount);
		this.initialAmount = Math.max(0, initialAmount);
		this.assignedLocation = assignedLocation == null ? "" : assignedLocation;
		this.active = active;
	}

	public static SlayerTaskContext none()
	{
		return NONE;
	}

	public String getTaskName()
	{
		return taskName;
	}

	public int getRemainingAmount()
	{
		return remainingAmount;
	}

	public int getInitialAmount()
	{
		return initialAmount;
	}

	public String getAssignedLocation()
	{
		return assignedLocation;
	}

	public boolean isActive()
	{
		return active;
	}
	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SlayerTaskContext))
		{
			return false;
		}
		SlayerTaskContext that = (SlayerTaskContext) other;
		return remainingAmount == that.remainingAmount
			&& initialAmount == that.initialAmount
			&& active == that.active
			&& Objects.equals(taskName, that.taskName)
			&& Objects.equals(assignedLocation, that.assignedLocation);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(taskName, remainingAmount, initialAmount, assignedLocation, active);
	}

}

package com.slayerprepassistant.task;

import com.slayerprepassistant.wiki.WikiTitles;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class TaskTargetResolver
{
	public List<TargetOption> resolve(SlayerTaskContext taskContext)
	{
		if (taskContext == null || !taskContext.isActive())
		{
			return Collections.emptyList();
		}

		String taskName = taskContext.getTaskName();
		if (taskName == null || taskName.trim().isEmpty())
		{
			return Collections.emptyList();
		}

		String title = WikiTitles.wikiTitle(taskName);
		if (title == null || title.trim().isEmpty())
		{
			title = taskName.trim();
		}

		TargetOption option = new TargetOption(title, title, "Strategies/" + title);
		return Collections.singletonList(option);
	}
}

package com.slayerprepassistant.task;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

public class TaskChatMessageParser
{
	private static final Pattern TASK_STATUS = Pattern.compile("(?i).*You have a Slayer task:\\s*([^\\.]+).*");
	private static final Pattern REMAINING = Pattern.compile("(?i).*You have\\s+(\\d+)\\s+(.+?)\\s+remaining\\.?$");
	private static final Pattern ASSIGNED = Pattern.compile("(?i).*(?:You're|You are) assigned to kill\\s+(?:(\\d+)\\s+)?(.+?)(?:\\.|;|$).*");
	private static final Pattern NEW_TASK = Pattern.compile("(?i).*Your new task is to kill\\s+(\\d+)\\s+(.+?)(?:\\.|;|$).*");
	private static final Pattern COMPLETE = Pattern.compile("(?i).*(?:completed your task|task is complete|no longer have a slayer task).*");

	public Optional<SlayerTaskContext> parse(String message, SlayerTaskContext previous)
	{
		String clean = Text.removeTags(message == null ? "" : message).replace('\u00a0', ' ').trim();
		if (clean.isEmpty())
		{
			return Optional.empty();
		}
		if (COMPLETE.matcher(clean).matches())
		{
			return Optional.of(SlayerTaskContext.none());
		}

		Matcher remaining = REMAINING.matcher(clean);
		if (remaining.matches())
		{
			int amount = parseAmount(remaining.group(1));
			String taskName = cleanTaskName(remaining.group(2));
			return Optional.of(new SlayerTaskContext(taskName, amount, previousInitial(previous, taskName, amount), previousLocation(previous, taskName), true));
		}

		Matcher newTask = NEW_TASK.matcher(clean);
		if (newTask.matches())
		{
			int amount = parseAmount(newTask.group(1));
			String taskName = cleanTaskName(newTask.group(2));
			return Optional.of(new SlayerTaskContext(taskName, amount, amount, "", true));
		}

		Matcher assigned = ASSIGNED.matcher(clean);
		if (assigned.matches())
		{
			int amount = parseAmount(assigned.group(1));
			String taskName = cleanTaskName(assigned.group(2));
			return Optional.of(new SlayerTaskContext(taskName, amount, amount, "", true));
		}

		Matcher taskStatus = TASK_STATUS.matcher(clean);
		if (taskStatus.matches())
		{
			String taskName = cleanTaskName(taskStatus.group(1));
			int rem = previousRemaining(previous, taskName);
			return Optional.of(new SlayerTaskContext(taskName, rem, previousInitial(previous, taskName, rem), previousLocation(previous, taskName), true));
		}

		return Optional.empty();
	}

	private int previousRemaining(SlayerTaskContext previous, String taskName)
	{
		if (previous == null || !previous.isActive() || taskName == null || previous.getTaskName() == null)
		{
			return 0;
		}
		return previous.getTaskName().equalsIgnoreCase(taskName) ? previous.getRemainingAmount() : 0;
	}

	private int previousInitial(SlayerTaskContext previous, String taskName, int fallback)
	{
		if (previous == null || !previous.isActive() || taskName == null || previous.getTaskName() == null)
		{
			return Math.max(0, fallback);
		}
		return previous.getTaskName().equalsIgnoreCase(taskName) ? previous.getInitialAmount() : Math.max(0, fallback);
	}

	private String previousLocation(SlayerTaskContext previous, String taskName)
	{
		if (previous == null || !previous.isActive() || taskName == null || previous.getTaskName() == null)
		{
			return "";
		}
		return previous.getTaskName().equalsIgnoreCase(taskName) ? (previous.getAssignedLocation() == null ? "" : previous.getAssignedLocation()) : "";
	}

	private int parseAmount(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return 0;
		}
		try
		{
			return Math.max(0, Integer.parseInt(value.trim()));
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	private String cleanTaskName(String value)
	{
		String cleaned = value == null ? "" : value.trim();
		if (cleaned.isEmpty())
		{
			return "";
		}
		cleaned = cleaned.replaceFirst("(?i)\\s+in\\s+.+$", "");
		return cleaned.replaceAll("\\s+", " ");
	}
}

